// AUTO-GENERATED (opus reflections workflow) — per-verse reflection + insight, keyed by verse.
export const REFLECTIONS: Record<string, { reflection: string; insight: string }> = {
  "逢佛殺佛": {"reflection": "When devotion to a teacher or idea hardens into clinging, it blocks the very freedom it promised. Hold your guides loosely; let no fixed image of the sacred replace your own direct, living understanding.", "insight": "Any concept of awakening, however holy, becomes an obstacle once mistaken for awakening itself."},
  "जै जै जै हनुमान गोसाईं। कृपा करहु गुरुदेव की नाईं॥": {"reflection": "Begin hard tasks not by sizing up your own strength but by invoking a greater grace to guide you. Approaching the day in this spirit of reverent appeal steadies the heart before effort begins.", "insight": "Surrendering to a higher guide as one's teacher is itself the first act of strength."},
  "तुलसीदास सदा हरि चेरा। कीजै नाथ हृदय महँ डेरा॥": {"reflection": "True devotion asks not for possessions but for the divine to dwell within. Carry the sacred in your heart through ordinary hours, and your inner life gains a steady, unshakeable center.", "insight": "The highest prayer is not for things but for the presence of the divine to abide within."},
  "पवनतनय संकट हरन, मंगल मूरति रूप। राम लखन सीता सहित, हृदय बसहु सुर भूप॥": {"reflection": "In times of trouble, turn inward to what is auspicious and protective rather than dwelling on the difficulty. Holding the sacred close in the heart reframes hardship as something you do not face alone.", "insight": "What dispels sorrow is not the absence of difficulty but the indwelling of the auspicious."},
  "सत्त्वं रजस्तम इति गुणाः प्रकृतिसम्भवाः । निबध्नन्ति महाबाहो देहे देहिनमव्ययम् ॥": {"reflection": "Your moods, drives, and dullness are natural forces, not your essence. Watching them rise and pass without identifying with them loosens their grip and reveals the steady awareness beneath.", "insight": "The true self is the imperishable witness, not the shifting qualities of nature that bind it to the body."},
  "本來無一物，何處惹塵埃。": {"reflection": "If the mind is not a fixed thing to be polished, then no defilement can truly stain it. Rather than anxiously cleaning your inner world, recognize the spaciousness in which all troubles arise and dissolve.", "insight": "When no separate self is grasped as real, there is nothing for impurity to cling to."},
  "盡界の盡有は、つらつら時なり。": {"reflection": "You are not moving through time as if it were a road outside you; each being and moment is time itself. Meeting this hour fully, you stop waiting for life and find it is already here.", "insight": "Existence is not contained within time; every being is a complete expression of time."},
  "आहारस्त्वपि सर्वस्य त्रिविधो भवति प्रियः । यज्ञस्तपस्तथा दानं तेषां भेदमिमं शृणु ॥": {"reflection": "Even your tastes in food, work, and giving reveal your inner disposition. Noticing what you are drawn to is a quiet mirror of your character, and a starting point for refining it.", "insight": "Our preferences in even the smallest choices disclose the quality of our inner nature."},
  "कंचन बरन बिराज सुबेसा। कानन कुंडल कुंचित केसा॥": {"reflection": "Dwelling on a luminous, dignified image of the divine lifts the mind from clutter toward beauty and order. Letting your attention rest on what is noble shapes the inner tone of your day.", "insight": "Contemplating beauty and radiance in the sacred draws the mind upward toward its source."},
  "仏道をならふといふは、自己をならふなり。自己をならふといふは、自己をわするるなり。": {"reflection": "Real spiritual study turns inward to know yourself, then dissolves even that self-preoccupation. As self-concern quiets, you become open and responsive to everything around you.", "insight": "The path turns from studying the self to forgetting it, until one is awakened by all things."},
  "महाबीर बिक्रम बजरंगी। कुमति निवार सुमति के संगी॥": {"reflection": "Strength of character is not only force but the clearing away of harmful thinking. Invoke courage to release a self-defeating thought today, and let sounder judgment keep you company instead.", "insight": "True valor includes the inner power to dispel corrupt thinking and befriend right understanding."},
  "तुम्हरो मंत्र बिभीषन माना। लंकेस्वर भए सब जग जाना॥": {"reflection": "Heeding wise counsel, even when it asks you to leave a familiar but flawed path, can raise you to a place you could not reach alone. Listening humbly is itself a form of greatness.", "insight": "Receptivity to wise counsel can lift a person to dignity that self-will alone never reaches."},
  "सनकादिक ब्रह्मादि मुनीसा। नारद सारद सहित अहीसा॥": {"reflection": "Even the wisest sages and gods devote themselves to praising the worthy. Honoring greatness beyond yourself is not weakness but the mark of a mature and humble mind.", "insight": "Reverence for the truly worthy is shared even by the wise, for humility befits greatness."},
  "संकट तें हनुमान छुड़ावै। मन क्रम बचन ध्यान जो लावै॥": {"reflection": "Relief comes when thought, word, and action are aligned in single-minded focus. Bringing your whole self to bear on what you turn toward steadies you through difficulty.", "insight": "Wholehearted devotion in thought, word, and deed is what releases one from distress."},
  "साधु संत के तुम रखवारे। असुर निकंदन राम दुलारे॥": {"reflection": "Strength finds its purpose in protecting the good and confronting what is destructive. Let your own capabilities be devoted to guarding what is decent rather than serving yourself alone.", "insight": "Power is rightly used when it shelters the good and opposes what harms."},
  "अधिष्ठानं तथा कर्ता करणं च पृथग्विधम् । विविधाश्च पृथक्चेष्टा दैवं चैवात्र पञ्चमम् ॥": {"reflection": "No outcome rests on your effort alone; circumstance, faculties, action, and forces beyond you all converge. Recognizing this tempers both excess pride in success and harsh blame in failure.", "insight": "Every action arises from many converging factors, not the doer's will alone."},
  "तमेव शरणं गच्छ सर्वभावेन भारत । तत्प्रसादात्परां शान्तिं स्थानं प्राप्स्यसि शाश्वतम् ॥": {"reflection": "When you give yourself wholly to a trust greater than your anxieties, peace ceases to depend on controlling outcomes. Whole-hearted surrender, not half-measures, is what brings lasting rest.", "insight": "Supreme peace comes through complete surrender to the divine, not partial reliance on oneself."},
  "正中偏：三更初夜月明前，莫怪相逢不相識": {"reflection": "In the dark before clarity dawns, do not be surprised when truth meets you unrecognized. Stay present in the not-yet-knowing; recognition ripens in its own time, not by force.", "insight": "Before insight fully dawns, reality is present yet unrecognized — and that obscurity is itself part of the way."},
  "सब सुख लहै तुम्हारी सरना। तुम रक्षक काहू को डर ना॥": {"reflection": "When you place a worry in trustworthy hands and truly let it rest there, the fear that drained you loosens its grip. Real refuge is what turns dread into steadiness.", "insight": "Security is not the absence of danger but the presence of a protector you can wholly trust."},
  "राम दूत अतुलित बल धामा। अंजनि-पुत्र पवनसुत नामा॥": {"reflection": "Hanuman's vast strength is described as service to Rama, not self-display. Let your own capability find its meaning in a cause larger than your ego.", "insight": "Strength becomes greatness only when devoted to something beyond oneself."},
  "हाथ बज्र औ ध्वजा बिराजै। काँधे मूँज जनेऊ साजै॥": {"reflection": "The thunderbolt and the sacred thread sit together: raw power and disciplined vows. True force in a life is force that has accepted restraint.", "insight": "Power and discipline belong together; might without sacred commitment is incomplete."},
  "बिद्यावान गुनी अति चातुर। राम काज करिबे को आतुर॥": {"reflection": "Learning, virtue, and cleverness here are matched by eagerness to act in service. Knowledge that stays idle is unfinished; let yours press toward useful work.", "insight": "Wisdom is fulfilled not in knowing but in the readiness to act for what is right."},
  "लाय सजीवन लखन जियाये। श्रीरघुबीर हरषि उर लाये॥": {"reflection": "Hanuman did whatever the crisis demanded to save a life, and the reward was a heartfelt embrace. Wholehearted help offered in another's emergency is its own deepest recognition.", "insight": "The truest reward for selfless service is the love it draws back to you."},
  "जय हनुमान ज्ञान गुन सागर। जय कपीस तिहुँ लोक उजागर॥": {"reflection": "Here wisdom and virtue are praised together as an ocean, not as separate boasts. Cultivate knowing and good character at once, so one lights the way the other walks.", "insight": "Knowledge and virtue, joined, become a light that brightens all around them."},
  "सूछ्म रूप धरि सियहिं दिखावा। बिकट रूप धरि लंक जरावा॥": {"reflection": "The same Hanuman grew gentle before Sita and fierce against Lanka. Maturity is meeting each moment in its true measure, soft where softness serves and strong where strength is needed.", "insight": "Right action means matching your response to the moment, not forcing one manner onto all situations."},
  "जो सत बार पाठ कर कोई। छूटहि बंदि महा सुख होई॥": {"reflection": "The verse promises freedom from bondage to the one who returns to it a hundred times. Sustained, repeated devotion, not a single hurried attempt, is what loosens what binds us.", "insight": "Release and lasting joy come through faithful repetition, not a single effort."},
  "जो यह पढ़ै हनुमान चालीसा। होय सिद्धि साखी गौरीसा॥": {"reflection": "The promised attainment is sealed by a divine witness, Shiva himself. When you commit to a sincere practice, trust that your steadfastness is seen, even when no human notices.", "insight": "Sincere devotion bears fruit, and that fruit is witnessed by the sacred itself."},
  "非風動，非旛動，仁者心動": {"reflection": "Two monks argued whether wind or flag moved; the truth was that their own minds stirred. Before blaming circumstances for your agitation, look at the mind doing the watching.", "insight": "Much of what we call outer disturbance is the movement of our own mind."},
  "तस्मात्त्वमुत्तिष्ठ यशो लभस्व जित्वा शत्रून्भुङ्क्ष्व राज्यं समृद्धम् । मयैवैते निहताः पूर्वमेव निमित्तमात्रं भव सव्यसाचिन् ॥": {"reflection": "Krishna tells Arjuna to rise and act while knowing the larger outcome is not his to author. Do your duty fully, yet hold lightly the illusion that you alone control results.", "insight": "We are called to act wholeheartedly while accepting we are instruments, not sole authors, of outcomes."},
  "जुग सहस्र जोजन पर भानू। लील्यो ताहि मधुर फल जानू॥": {"reflection": "The child Hanuman leapt at the distant sun, undaunted by its impossible distance. A fearless, innocent confidence can attempt what calculation would call out of reach.", "insight": "Bold faith perceives possibility where cautious reckoning sees only impossibility."},
  "प्रभु मुद्रिका मेलि मुख माहीं। जलधि लाँघि गये अचरज नाहीं॥": {"reflection": "Carrying his Lord's token, Hanuman crossed the ocean as though it were nothing. When you act in trust for something you hold sacred, obstacles that loom large can be passed.", "insight": "A heart anchored in devotion crosses barriers that seem insurmountable on their own."},
  "क्लेशोऽधिकतरस्तेषामव्यक्तासक्तचेतसाम् । अव्यक्ता हि गतिर्दुःखं देहवद्भिरवाप्यते ॥": {"reflection": "The Gita admits the abstract, formless path is harder for embodied beings. Honor your own limits: a concrete, relatable practice is no lesser for being easier to hold.", "insight": "The path suited to your nature serves you better than a loftier one you cannot truly hold."},
  "古池や蛙飛び込む水の音": {"reflection": "A frog enters an old pond and a single sound breaks the stillness. Full attention to one small ordinary moment can open a quiet depth the busy mind walks past.", "insight": "Complete presence to an ordinary instant reveals a depth hidden in plain sight."},
  "अनुद्वेगकरं वाक्यं सत्यं प्रियहितं च यत् । स्वाध्यायाभ्यसनं चैव वाङ्मयं तप उच्यते ॥": {"reflection": "Speech that is true, kind, helpful, and untroubling is named a discipline here, alongside steady study. Before speaking, weigh your words on all four counts; restraint of the tongue is real spiritual work.", "insight": "Truthful, kind, and beneficial speech is a genuine austerity, not mere politeness."},
  "चारों जुग परताप तुम्हारा। है परसिद्ध जगत उजियारा॥": {"reflection": "Hanuman's glory is said to endure across all ages because it rests on faithful service. What we build on devotion and good deeds outlasts what we build on passing acclaim.", "insight": "Renown founded on selfless virtue endures far beyond any single age."},
  "रघुपति कीन्ही बहुत बड़ाई। तुम मम प्रिय भरतहि सम भाई॥": {"reflection": "Rama held his devoted servant as dear as his own brother. Loyal, loving service can forge a closeness as deep as any blood bond.", "insight": "Devoted service can create a kinship of the heart as strong as family."},
  "यो च वस्ससतं जीवे अपस्सं उदयब्बयं । एकाहं जीवितं सेय्यो पस्सतो उदयब्बयं ॥": {"reflection": "A life measured in years means little if you never notice how things arise and pass. Spend one honest day watching your moods, gains and losses come and go, and you live more truly than in decades of distraction.", "insight": "Depth of awareness, not length of years, is the real measure of a life well lived."},
  "両手を打ち合わせると音がする。では、片手にはどんな音があるのか？": {"reflection": "When the mind is stuck reaching for tidy answers, this question refuses to give one. Sit with a problem that has no neat solution and let it loosen the grip of needing everything explained.", "insight": "Some truths are met not by reasoning them out but by letting the reasoning mind fall silent."},
  "सर्वधर्मान्परित्यज्य मामेकं शरणं व्रज । अहं त्वां सर्वपापेभ्यो मोक्षयिष्यामि मा शुचः ॥": {"reflection": "When you have done your duty and still feel the weight of every rule and outcome, this verse offers rest: surrender the burden wholeheartedly to the Divine and stop carrying fear alone.", "insight": "Total trust in the Divine releases the soul from the anxiety of having to secure itself."},
  "अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च । निर्ममो निरहङ्कारः समदुःखसुखः क्षमी ॥": {"reflection": "The person dear to God is described plainly: free of malice, friendly and compassionate, unowning, steady in pleasure and pain, forgiving. Practice these not as lofty ideals but as how you treat the next person you meet.", "insight": "Spiritual nearness to the Divine is shown through ordinary kindness, equanimity and the absence of ego."},
  "至道無難，唯嫌揀擇。": {"reflection": "Much of our daily strain comes from constant sorting into liked and disliked. Meet your morning, your work, the weather without the reflex of picking sides, and the path forward feels far less difficult.", "insight": "The mind's habit of preference, not reality itself, is what makes the way seem hard."},
  "प्रकृतेः क्रियमाणानि गुणैः कर्माणि सर्वशः । अहङ्कारविमूढात्मा कर्ताहमिति मन्यते ॥": {"reflection": "When pride swells over a success or shame over a failure, remember that nature's own forces do much of the doing through you. Act fully, but loosen the grip of 'I alone am the doer.'", "insight": "The ego's claim to sole authorship of action is a delusion that breeds both vanity and despair."},
  "मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु । मामेवैष्यसि सत्यं ते प्रतिजाने प्रियोऽसि मे ॥": {"reflection": "Devotion need not be complicated: keep the Divine in mind, offer your work, and bow with sincerity. Woven through an ordinary day, these simple acts steadily turn the heart toward what is highest.", "insight": "A life quietly oriented toward the Divine in thought and offering is itself the path home."},
  "ठितो अहं अङ्गुलिमाल सब्बदा, सब्बेसु भूतेसु निधाय दण्डं।": {"reflection": "The Buddha had 'stopped' by laying down all harm toward living beings, while the one chasing him had not. Ask where you are still running, and what it would mean to set down your own weapons today.", "insight": "True peace is not arrival at a place but the inner ceasing of harm toward every living thing."},
  "इन्द्रियाणि पराण्याहुरिन्द्रियेभ्यः परं मनः । मनसस्तु परा बुद्धिर्यो बुद्धेः परतस्तु सः ॥": {"reflection": "When senses pull you one way and impulse another, this verse maps the inner hierarchy: above the senses is the mind, above mind the discerning intellect, and above all the Self. Govern from the higher, not the lower.", "insight": "Mastery comes from aligning the senses and mind under reason, and reason under the Self."},
  "अहं सर्वस्य प्रभवो मत्तः सर्वं प्रवर्तते । इति मत्वा भजन्ते मां बुधा भावसमन्विताः ॥": {"reflection": "Seeing the Divine as the source from which everything flows reframes daily life as gift rather than possession. Let that recognition turn ordinary gratitude into wholehearted devotion.", "insight": "Knowing the one Source behind all things naturally ripens into love and worship."},
  "वयधम्मा सङ्खारा, अप्पमादेन सम्पादेथ।": {"reflection": "The Buddha's last words held no drama, only clarity: all formed things decay, so press on attentively. Let the certainty of impermanence make you more diligent today, not more anxious.", "insight": "Accepting that all things pass is precisely what gives urgency and seriousness to spiritual effort."},
  "श्रद्धावाँल्लभते ज्ञानं तत्परः संयतेन्द्रियः। ज्ञानं लब्ध्वा परां शान्तिमचिरेणाधिगच्छति॥": {"reflection": "Knowledge that brings peace asks three things of us: faith, wholehearted attention, and restraint of the senses. Cultivate these and understanding ripens, and with it a settled calm.", "insight": "Faith, focus and self-restraint are the conditions through which knowledge matures into lasting peace."},
  "यथा दीपो निवातस्थो नेङ्गते सोपमा स्मृता। योगिनो यतचित्तस्य युञ्जतो योगमात्मनः॥": {"reflection": "A flame sheltered from wind burns perfectly still. Shield your attention from the gusts of notification and worry, and the mind, like that lamp, can finally hold steady and clear.", "insight": "The disciplined mind, protected from disturbance, attains the unwavering steadiness of a sheltered flame."},
  "यो मां पश्यति सर्वत्र सर्वं च मयि पश्यति। तस्याहं न प्रणश्यामि स च मे न प्रणश्यति॥": {"reflection": "To see the Divine in everyone and everything dissolves the sense of being cut off. Practice this seeing and you are never truly alone, nor ever lost to the One who holds all.", "insight": "Perceiving the Divine everywhere establishes an unbreakable bond that no circumstance can sever."},
  "अनेकाजातिसंसारं सन्धाविस्सं अनिब्बिसं। गहकारकं गवेसन्तो दुक्खा जाति पुनप्पुनं॥": {"reflection": "These were the Buddha's words at awakening, after long seeking the 'builder' of suffering's house. When pain recurs, look for its inner maker, the craving and clinging, rather than only its outward cause.", "insight": "Suffering repeats until we recognize and release the craving that keeps constructing it."},
  "अनन्याश्चिन्तयन्तो मां ये जनाः पर्युपासते। तेषां नित्याभियुक्तानां योगक्षेमं वहाम्यहम्॥": {"reflection": "To those who turn to the Divine with undivided heart, this verse promises care: what is lacking is supplied, what is held is preserved. Devotion need not be anxious; you are looked after.", "insight": "Wholehearted, single-minded devotion is met by the Divine's own provision and protection."},
  "南無妙法蓮華経": {"reflection": "This chant is wholehearted devotion to the truth of the Lotus Sutra. Repeating it gathers a scattered mind to a single sacred point and renews reverence amid a busy day.", "insight": "Sincere repetition of the sacred Law focuses the heart and expresses complete devotion."},
  "मनुष्याणां सहस्रेषु कश्चिद्यतति सिद्धये। यततामपि सिद्धानां कश्चिन्मां वेत्ति तत्त्वतः॥": {"reflection": "Few even begin to strive for the highest, and fewer still truly know the Divine. Let this not discourage but sober you: rare effort is asked, so give your seeking real seriousness.", "insight": "Genuine realization of the Divine is rare and demands earnest, persistent striving."},
  "दैवी ह्येषा गुणमयी मम माया दुरत्यया। मामेव ये प्रपद्यन्ते मायामेतां तरन्ति ते॥": {"reflection": "Willpower alone rarely frees us from the patterns that bind us. When you stop wrestling and instead surrender to a higher truth, the grip of illusion quietly loosens.", "insight": "What cannot be conquered by effort is crossed through refuge in the divine."},
  "श्रीभगवानुवाच । कालोऽस्मि लोकक्षयकृत्प्रवृद्धो लोकान्समाहर्तुमिह प्रवृत्तः । ऋतेऽपि त्वां न भविष्यन्ति सर्वे येऽवस्थिताः प्रत्यनीकेषु योधाः ॥": {"reflection": "Time will dissolve all that we cling to whether we act or not. Recognizing this frees you to do your duty with courage instead of clutching at outcomes you were never meant to control.", "insight": "All things move toward their end in time; our task is to act, not to possess the result."},
  "राजविद्या राजगुह्यं पवित्रमिदमुत्तमम्। प्रत्यक्षावगमं धर्म्यं सुसुखं कर्तुमव्ययम्॥": {"reflection": "The deepest wisdom is not abstract; it can be felt directly in lived experience. Pursue knowledge that you can verify in your own heart and that makes daily practice lighter, not heavier.", "insight": "The highest knowledge is one verified through direct experience, not mere belief."},
  "यदा यदा हि धर्मस्य ग्लानिर्भवति भारत। अभ्युत्थानमधर्मस्य तदात्मानं सृजाम्यहम्॥": {"reflection": "When wrongdoing seems to overwhelm what is right, this verse reassures us that righteousness is never abandoned. Hold to your principles even in dark seasons, trusting that the moral order restores itself.", "insight": "Whenever righteousness declines, the divine acts to renew it."},
  "समोऽहं सर्वभूतेषु न मे द्वेष्योऽस्ति न प्रियः। ये भजन्ति तु मां भक्त्या मयि ते तेषु चाप्यहम्॥": {"reflection": "The divine plays no favorites; grace is offered equally to all. What draws us close is not status but sincere devotion, a relationship we enter through our own open-hearted turning.", "insight": "The divine is impartial to all, yet intimately present to those who love sincerely."},
  "माता यथा नियं पुत्तं आयुसा एकपुत्तमनुरक्खे । एवम्पि सब्बभूतेसु मानसं भावये अपरिमाणं ॥": {"reflection": "Recall the fierce tenderness a mother holds for her only child, then let that same care widen to every living being you meet today, without limit or exception.", "insight": "Boundless loving-kindness extends a mother's protective love to all beings alike."},
  "ततः स विस्मयाविष्टो हृष्टरोमा धनञ्जयः। प्रणम्य शिरसा देवं कृताञ्जलिरभाषत॥": {"reflection": "When met with something truly vast, the honest response is wonder and humility. Let awe soften your pride; bowing before what exceeds you is a strength, not a weakness.", "insight": "Genuine encounter with the sacred evokes humility and reverent wonder."},
  "पितासि लोकस्य चराचरस्य त्वमस्य पूज्यश्च गुरुर्गरीयान्। न त्वत्समोऽस्त्यभ्यधिकः कुतोऽन्यो लोकत्रयेऽप्यप्रतिमप्रभाव॥": {"reflection": "To honor a source greater than ourselves rightly orders the heart. Acknowledging that something is worthy of our deepest respect keeps us humble and grateful rather than self-important.", "insight": "Reverence for the supreme source places one's life in its true proportion."},
  "तुल्यनिन्दास्तुतिर्मौनी सन्तुष्टो येन केनचित्। अनिकेतः स्थिरमतिर्भक्तिमान्मे प्रियो नरः॥": {"reflection": "Inner steadiness means praise no longer inflates you and blame no longer wounds you. Practice contentment with what comes and a quiet mind, holding lightly to where you stand.", "insight": "The devotee dear to the divine rests in steadiness, unmoved by praise, blame, or circumstance."},
  "सुखदुःखे समे कृत्वा लाभालाभौ जयाजयौ । ततो युद्धाय युज्यस्व नैवं पापमवाप्स्यसि ॥": {"reflection": "Do your work fully while holding gain and loss, win and defeat, in even balance. This equanimity lets you act rightly without being corrupted by craving for success or fear of failure.", "insight": "Acting with equanimity toward all outcomes keeps duty free of sin."},
  "ये हि संस्पर्शजा भोगा दुःखयोनय एव ते । आद्यन्तवन्तः कौन्तेय न तेषु रमते बुधः ॥": {"reflection": "Pleasures from outer things always arrive and then depart, and chasing them leaves a familiar ache. Enjoy them lightly, knowing lasting contentment is not found in what begins and ends.", "insight": "Sense-pleasures, being transient, cannot be the ground of lasting happiness."},
  "असंशयं महाबाहो मनो दुर्निग्रहं चलम् । अभ्यासेन तु कौन्तेय वैराग्येण च गृह्यते ॥": {"reflection": "A restless mind is not a personal failing but a universal one, and it is not hopeless. Steady, repeated practice paired with loosening attachments gradually brings it under your guidance.", "insight": "The restless mind is mastered not at once but through patient practice and dispassion."},
  "महात्मानस्तु मां पार्थ दैवीं प्रकृतिमाश्रिताः । भजन्त्यनन्यमनसो ज्ञात्वा भूतादिमव्ययम् ॥": {"reflection": "Great-hearted people give their devotion wholly, without a divided or distracted mind. Aim to bring that same undivided attention to what you hold sacred, instead of half-hearted worship.", "insight": "The noble worship the imperishable source with an undivided, single-pointed mind."},
  "इति ते ज्ञानमाख्यातं गुह्याद्गुह्यतरं मया । विमृश्यैतदशेषेण यथेच्छसि तथा कुरु ॥": {"reflection": "Even the highest teaching is offered, never imposed. Reflect on what you have learned fully and then choose freely; genuine wisdom honors your responsibility to decide for yourself.", "insight": "True teaching invites full reflection and leaves the freedom to choose with the learner."},
  "अध्येष्यते च य इमं धर्म्यं संवादमावयोः । ज्ञानयज्ञेन तेनाहमिष्टः स्यामिति मे मतिः ॥": {"reflection": "Sincere study of sacred truth is itself a form of worship. The time you give to understanding and reflecting on wisdom is not idle; it is an offering in its own right.", "insight": "The earnest study of sacred knowledge is honored as a sacrifice in itself."},
  "यस्य नाहङ्कृतो भावो बुद्धिर्यस्य न लिप्यते । हत्वापि स इमाँल्लोकान्न हन्ति न निबध्यते ॥": {"reflection": "When action arises without the ego's claim of 'I am the doer,' the heart stays unstained even amid difficult duty. Act from clear, selfless intention rather than self-importance.", "insight": "Action free of egoism and attachment does not bind the one who performs it."},
  "Seyyathāpi, mālukyaputta, puriso sallena viddho assa savisena gāḷhūpalepanena. Tassa mittāmaccā ñātisālohitā bhisakkaṃ sallakattaṃ upaṭṭhāpeyyuṃ. So evaṃ vadeyya: 'Na tāvāhaṃ imaṃ sallaṃ āharissāmi yāva na taṃ purisaṃ jānāmi yenamhi viddho — khattiyo vā brāhmaṇo vā vesso vā suddo vā'ti...": {"reflection": "When you are suffering, attend to the wound first rather than demanding every speculative answer. Tend to what eases real pain now; some questions can wait, or never need answering at all.", "insight": "Liberation begins with addressing actual suffering, not with endless speculation."},
  "इदं खलु पुनर्भिक्षवो दुःखमार्यसत्यम् — जातिरपि दुःखा, जरापि दुःखा, व्याधिरपि दुःखो, मरणमपि दुःखम्, अप्रियैः संप्रयोगो दुःखः, प्रियैर्विप्रयोगो दुःखः, यदपीच्छन्न लभते तदपि दुःखम् — संक्षेपेण पञ्चोपादानस्कन्धा दुःखाः॥": {"reflection": "Naming suffering honestly, in aging, loss, and unmet wants, is not pessimism but clarity. Seeing where pain truly arises is the first step toward meeting it wisely instead of denying it.", "insight": "Honestly recognizing suffering and its forms is the foundation of the path beyond it."},
  "रूपं, भिक्षवो, अनात्मा। रूपञ्च हीदं, भिक्षवो, आत्मा अभविष्यत्, नेदं रूपमाबाधाय संवर्तेत, लभ्येत च रूपे: 'एवं मे रूपं भवतु, एवं मे रूपं मा अभूद्' इति।": {"reflection": "When your body ages, sickens, or refuses to look the way you wish, it isn't betraying you — it was never fully yours to command. Holding it loosely eases the quiet war we wage against our own aging and illness.", "insight": "Suffering arises from treating what we cannot control as if it were our possession and self."},
  "सर्वं, भिक्षवो, आदीप्तम्। किञ्च, भिक्षवो, सर्वमादीप्तम्? चक्षुः, भिक्षवो, आदीप्तम्; रूपाण्यादीप्तानि; चक्षुर्विज्ञानमादीप्तम्... केनादीप्तम्? रागाग्निना, द्वेषाग्निना, मोहाग्निनादीप्तम्।": {"reflection": "Notice how scrolling, craving, and irritation set your senses smoldering all day. The fire isn't in the world but in how greed, aversion, and confusion meet what you see — and that fire can be let go.", "insight": "Experience burns not by its objects but by the craving, hatred, and delusion we bring to perceiving them."},
  "अविद्याप्रत्ययात् संस्काराः; संस्कारप्रत्ययाद् विज्ञानम्; विज्ञानप्रत्ययान् नामरूपम्; नामरूपप्रत्ययात् षडायतनम्; षडायतनप्रत्ययात् स्पर्शः; स्पर्शप्रत्ययाद् वेदना; वेदनाप्रत्ययात् तृष्णा; तृष्णाप्रत्ययाद् उपादानम्; उपादानप्रत्ययाद् भवः; भवप्रत्ययाज् जातिः; जातिप्रत्ययाज् जरामरणम्।": {"reflection": "Distress rarely strikes from nowhere; it links from contact to feeling to craving to clinging. Catching the chain early — at the bare feeling, before it hardens into wanting — is where freedom actually opens.", "insight": "Suffering is conditioned, arising in a traceable chain, so it can also be unmade by interrupting its links."},
  "एत यूयम्, कालामाः, मा अनुश्रवेण, मा परम्परया, मा इतिकिरया, मा पिटकसम्प्रदानेन, मा तर्कहेतोः, मा नयहेतोः, मा आकारपरिवितर्केण, मा दृष्टिनिध्यानक्षान्त्या, मा भव्यरूपतया, मा 'श्रमणो नो गुरुः' इति।": {"reflection": "Before accepting a claim — from tradition, a clever argument, or a charismatic voice — test it against what you can actually see leads to good. Inherited belief and impressive speakers are no substitute for honest examination.", "insight": "True conviction rests not on authority or rhetoric but on what one verifies through direct understanding."},
  "'देवो नु भवान् भविष्यती'ति? 'न खल्वहं, ब्राह्मण, देवो भविष्यामी'ति... 'मनुष्यो नु भवान् भविष्यती'ति? 'न खल्वहं, ब्राह्मण, मनुष्यो भविष्यामी'ति. 'किं पुनर्भवान् भविष्यती'ति? 'बुद्धो'ति.": {"reflection": "When asked what he was, the Buddha claimed no title of god or rank — only that he was awake. Awakening isn't a status to acquire but a clarity available to anyone who truly sees.", "insight": "Liberation is defined not by what one becomes but by being awake to things as they are."},
  "पञ्चेमानि, भिक्षवो, स्थानानि अभीक्ष्णं प्रत्यवेक्षितव्यानि स्त्रिया वा पुरुषेण वा गृहस्थेन वा प्रव्रजितेन वा: जराधर्मोऽस्मि, जराम् अनतीतो... व्याधिधर्मोऽस्मि... मरणधर्मोऽस्मि... सर्वैः मे प्रियैः मनापैः नानाभावो विनाभावो... कर्मस्वकोऽस्मि।": {"reflection": "Quietly recalling that we will age, sicken, lose what we love, and die isn't morbid — it loosens our grip on the trivial. Remembering we own our actions turns each day toward what we can still do well.", "insight": "Honest contemplation of mortality and our ownership of our deeds reorders what we treat as urgent."},
  "अष्टाविमे, भिक्षवो, लोकधर्मा लोकमनुपरिवर्तन्ते, लोकश्चाष्टौ लोकधर्माननुपरिवर्तते। कतमेऽष्टौ? लाभश्च, अलाभश्च, यशश्च, अयशश्च, निन्दा च, प्रशंसा च, सुखञ्च, दुःखञ्च।": {"reflection": "Praise and blame, gain and loss, will keep blowing through your life like weather. Knowing they always come in pairs lets you stay steady — neither inflated by applause nor crushed by criticism.", "insight": "Equanimity comes from recognizing that fortune and its opposite are inseparable, recurring conditions of any life."},
  "द्वे इमे, भिक्षवः, पर्येषणे — आर्या च पर्येषणा, अनार्या च पर्येषणा। कतमा च, भिक्षवः, अनार्या पर्येषणा? इह, भिक्षवः, एकत्यः आत्मना जातिधर्मा समानो जातिधर्ममेव पर्येषते... कतमा च, भिक्षवः, आर्या पर्येषणा? इह, भिक्षवः, एकत्यः आत्मना जातिधर्मा समानो जातिधर्मे आदीनवं विदित्वा अजातमनुत्तरं योगक्षेमं निर्वाणं पर्येषते।": {"reflection": "Chasing things as fragile as ourselves — wealth, status, fleeting comforts — only binds us to their decay. The worthier search seeks a security that change cannot touch, beginning by seeing the danger in the perishable.", "insight": "The noble search turns from pursuing the impermanent toward the unconditioned that is free of decay."},
  "'यत्र च पुनरहं, भिक्षो, प्रज्ञाविमुक्तिं चानुत्तरं शान्तिपदं चाकीर्तयम्। यथा खलु पुनर्, भिक्षो, प्रज्ञामधिष्ठतः प्रज्ञा न परिहीयते, सत्यमधिष्ठतः सत्यमनुवर्धते, त्यागमधिष्ठतः त्यागोऽनुवर्धते, उपशममधिष्ठतः उपशमोऽनुबृंह्यते।'": {"reflection": "Whatever you stand firmly upon, grows. Commit steadily to wisdom, honesty, letting-go, and inner calm, and each quietly deepens — not through a single grand effort but through being unshakably grounded in it.", "insight": "Steadfast dedication to a virtue is what causes it to strengthen rather than erode over time."},
  "इह, भिक्षवः, अश्रुतवान् पृथग्जनः... पृथिवीं पृथिवितः संजानाति; पृथिवीं पृथिवितः संज्ञाय पृथिवीं मन्यते, पृथिव्यां मन्यते, पृथिवितो मन्यते, 'पृथिवी मे' इति मन्यते, पृथिवीमभिनन्दति। तत् कस्य हेतोः? 'अपरिज्ञातं तस्य' इति वदामि।": {"reflection": "We rarely meet things plainly; we instantly fold them into 'me' and 'mine' and delight in possessing them. Seeing that reflex — turning every experience into self-reference — is the start of understanding it fully.", "insight": "Unexamined perception silently converts raw experience into a self that owns and identifies with it."},
  "हन्तेदानीं, भिक्षवः, आमन्त्रयामि वः— व्ययधर्माः संस्काराः, अप्रमादेन सम्पादयत।": {"reflection": "These were the Buddha's last words: everything made will pass. Rather than despair, let that truth sharpen your attention — do what matters now, carefully and without delay, while you still can.", "insight": "Impermanence is not cause for resignation but a summons to live with diligent attentiveness."},
  "नान्तरिक्षे न समुद्रमध्ये न पर्वतानां विवरं प्रविश्य। न विद्यते स जगत्प्रदेशो यत्रस्थितो मुच्येत पापकर्मणः॥": {"reflection": "No distance or hiding place outruns the consequences of how we act. Since we carry our deeds with us, the only real freedom is to act rightly now, not to escape what is already done.", "insight": "The results of our actions follow us inescapably, making integrity wiser than evasion."},
  "तस्मादिहानन्द, आत्मद्वीपा विहरत आत्मशरणा अनन्यशरणाः, धर्मद्वीपा धर्मशरणा अनन्यशरणाः।": {"reflection": "When you feel adrift, the steadiest ground is your own disciplined practice and the truth you've tested, not someone else rescuing you. Be your own island; let wise principle, not dependence, be your refuge.", "insight": "Genuine security comes from cultivating oneself in accord with truth rather than relying on external rescue."},
  "एकायनोऽयं, भिक्षवः, मार्गः सत्त्वानां विशुद्धये, शोकपरिदेवानां समतिक्रमाय, दुःखदौर्मनस्यानामस्तङ्गमाय, न्यायस्याधिगमाय, निर्वाणस्य साक्षात्क्रियायै, यदिदं चत्वारः स्मृत्युपस्थानाः।": {"reflection": "Sustained, honest attention to body, feelings, mind, and experience is offered as the direct road past grief and sorrow. Not a technique among many, but a steady practice of seeing clearly what is happening within.", "insight": "Mindful awareness of one's own experience is the path that leads through sorrow to freedom."},
  "आक्रोशीन्मामवधीन्मामजैषीन्मामहार्षीन्मे। ये तूपनह्यन्ति वैरं तेषां न शाम्यति॥ आक्रोशीन्मामवधीन्मामजैषीन्मामहार्षीन्मे। ये तु नोपनह्यन्ति वैरं तेषामुपशाम्यति॥": {"reflection": "Replaying 'he wronged me' keeps the wound — and the resentment — alive long after the event. Setting down the grievance, not the memory, is what finally lets the hostility in your own heart subside.", "insight": "Hatred is sustained by clinging to the story of injury, and ceases only when that grievance is released."},
  "अल्पमपि चेत् सहितं भाषमाणो धर्मस्य भवत्यनुधर्मचारी। रागं च दोषं च प्रहाय मोहं सम्यक्प्रजानः सुविमुक्तचित्तः। अनुपाददानो इह वा अमुत्र वा स भागवान् श्रामण्यस्य भवति॥": {"reflection": "Knowing many teachings counts for little if you don't live them. Even a little understanding, genuinely practiced — letting go of craving and ill-will, clinging to nothing — bears the real fruit of the path.", "insight": "Spiritual benefit comes from acting on what one knows, not from the quantity one has merely learned."},
  "सहस्रमपि चेद्वाचामनर्थपदसंहिताम्। एकमर्थपदं श्रेयो यच्छ्रुत्वोपसंशाम्यति॥": {"reflection": "A thousand empty words leave the mind no calmer than before. One sentence that actually settles the heart is worth more than all our restless chatter — speak and listen for what brings peace.", "insight": "The value of words lies not in their quantity but in whether they lead the mind toward peace."},
  "अन्धभूतोऽयं लोकोऽस्मिन् तनुकः सम्पश्यति। शकुन्तिर्जालमुक्तो वा स्वल्पः स्वर्गाय गच्छति॥": {"reflection": "Most of us move through life half-seeing, caught in the same nets of habit and craving. Clear sight is rare and freeing — like a bird slipping the snare — and worth the effort to cultivate honestly.", "insight": "Clear understanding is uncommon, and it is precisely what frees one from the entanglements that bind most lives."},
  "यथापि मूलेऽनुपद्रुते दृढे छिन्नोऽपि वृक्षः पुनरेव रोहति। एवमपि तृष्णानुशयेऽनूहते निर्वर्तते दुःखमिदं पुनः पुनः॥": {"reflection": "Breaking a bad habit on the surface isn't enough; if the craving beneath it stays alive, the trouble grows back. Lasting change means addressing the wanting at the root, not just its visible branches.", "insight": "Suffering recurs as long as the latent root of craving remains; only uprooting that tendency ends the cycle."},
  "अस्ति भिक्षवोऽजातमभूतमकृतमसंस्कृतम्। नो चेदिदं भिक्षवोऽभविष्यदजातमभूतमकृतमसंस्कृतं नेह जातस्य भूतस्य कृतस्य संस्कृतस्य निःसरणं प्रज्ञायेत।": {"reflection": "Amid all that is made, changing, and conditioned in your life, there is something unmade and unconditioned. Knowing it exists is what makes genuine freedom from the rush of circumstances possible.", "insight": "Liberation from the conditioned world is conceivable only because there is an unborn, unconditioned reality."},
  "अक्रोधेन जयेत् क्रोधमसाधुं साधुना जयेत्। जयेत् कदर्यं दानेन सत्येनालीकवादिनम्॥": {"reflection": "When met with anger, miserliness, or deceit, answer with their opposites rather than mirroring them. Meeting anger with calm and dishonesty with truth is the only way to actually win the encounter.", "insight": "True victory overcomes a vice by embodying its opposite, never by matching it."},
  "असेवना च बालानां पण्डितानां च सेवना। पूजा च पूजनीयानामेतन्मङ्गलमुत्तमम्॥": {"reflection": "The company you keep shapes who you become. Choosing wise companions over foolish ones, and honoring those who deserve respect, is among the most fortunate choices you can make.", "insight": "Good fortune begins with discernment in association: avoiding the foolish, drawing near the wise."},
  "चित्तमात्रं लोकमिदं द्वयं तत्र न विद्यते। विकल्पं पश्यते द्वयं न जानाति स्वचित्तकम्॥": {"reflection": "The sharp divisions you perceive between self and other, good and bad, often arise from the mind's own habit of splitting. Recognizing how much of conflict is mind-made softens it.", "insight": "Duality is a projection of the discriminating mind, not an inherent feature of reality."},
  "अथ तूष्णीम्भावेनावस्थितः। तत्र मञ्जुश्रीः कुमारभूतो विमलकीर्तिं लिच्छविं साधुकारमदात्- 'साधु साधु, कुलपुत्र, अयमेवाद्वयधर्ममुखप्रवेशो बोधिसत्त्वानां यत्र न रुतो न रवितो न व्याहारो न व्यञ्जनं न विज्ञप्तिः।'": {"reflection": "Some truths are diminished the moment we try to explain them. Vimalakirti's silence teaches that there are understandings best honored by saying nothing, not by adding more words.", "insight": "The deepest non-dual realization lies beyond sound, speech, and concept — it is entered through silence."},
  "यत् किञ्चिज्जगति सौख्यं सर्वं तत् परसौख्यतः। यत् किञ्चिज्जगति दुःखं सर्वं तत् स्वसुखेच्छया॥": {"reflection": "Consider how much of your contentment has come from giving or caring, and how much misery from grasping for yourself alone. Turning attention toward others' wellbeing is a quiet source of your own.", "insight": "Happiness flows from wishing others well; suffering from seeking happiness for oneself alone."},
  "बोधिचित्तोदयादेव संसारमहाकारागारबद्धाः। सुगतात्मजाः समाख्याताः सदेवलोके वन्द्याश्च स्युर्नरामरैः॥": {"reflection": "However bound by struggle you feel, the moment a sincere wish to awaken and help others arises in you, your dignity changes entirely. That single intention is itself worthy of reverence.", "insight": "The very arising of the awakening-mind ennobles a being, regardless of their outward bondage."},
  "यः प्रतीत्यसमुत्पादः शून्यतां तां प्रचक्ष्महे। सा प्रज्ञप्तिरुपादाय प्रतिपत् सैव मध्यमा॥": {"reflection": "Everything in your life arises in dependence on countless other things, so nothing stands fixed and alone. Holding that truth lightly, without clinging even to 'emptiness,' is the balanced middle way.", "insight": "Emptiness is just dependent arising seen rightly — a designation, not a thing — and this is the middle way."},
  "हीनमध्यविशिष्टत्वात् पुरुषास्त्रिविधा मताः। लक्षणं तेषु लिख्येत स्फुटं प्रत्येकभेदतः॥": {"reflection": "Examine what you are actually aiming for: mere pleasure, personal release, or the freedom of all beings. The reach of your aspiration quietly determines the stature of your path.", "insight": "A person's spiritual level is measured by the scope of their aim — from self-pleasure to the liberation of all."},
  "यश्च ते स्मरेत नित्यं सत्कुर्वीत जिनात्मजम्। करुणामय आर्यावलोकितेश्वरं नमोऽस्तु ते॥": {"reflection": "When overwhelmed by trouble, calling out wholeheartedly to compassion is never wasted. The verse promises that sincere appeal is heard and that the fiercest dangers lose their power to consume you.", "insight": "Wholehearted appeal to boundless compassion is met with deliverance, even in extremity."},
  "अचिन्त्यकल्पकोटीरहं बोधिप्राप्तपश्चात्। सतताभिरूढ इमं सद्धर्म देशयामि॥": {"reflection": "Guidance toward what is good has been present far longer and more constantly than we realize. Even apparent absences can be skillful means; the support for awakening has never truly withdrawn.", "insight": "The Buddha's compassionate teaching is unceasing; his vanishing is only a skillful means, not a real departure."},
  "मैत्रीं च सर्वलोकस्मिन् मानसं भावयेदपरिमाणम्। ऊर्ध्वमधश्च तिर्यक्च असम्बाधमवैरमसपत्नम्॥": {"reflection": "Loving-kindness need not be rationed to those who deserve it. Practice extending warmth in every direction without exception, holding no one as an enemy and letting it know no boundary.", "insight": "Loving-kindness reaches its fullness only when it is boundless, impartial, and free of all enmity."},
  "洞山和尚、因僧問、如何是佛。山云、麻三斤。": {"reflection": "When asked the loftiest question, Tozan pointed to plain flax at hand. The sacred isn't found by escaping ordinary life; it is fully present in the most concrete, humble task before you.", "insight": "The ultimate is not separate from the ordinary; awakening meets us in the plain thing at hand."},
  "香嚴和尚云、如人上樹、口啣樹枝、手不攀枝、脚不踏樹。樹下有人、問西來意。不對即違他所問、若對又喪身失命。正恁麼時、作麼生對。": {"reflection": "Life sometimes corners you where every option seems to fail. This koan presses you past clever calculation toward a response that comes from your whole being, not from weighing gain and loss.", "insight": "Some truths can only be answered by letting go of self-preserving calculation entirely."},
  "不思善不思惡、正與麼時、那個是明上座本來面目。": {"reflection": "Before you label anything good or bad, there is simply you, awake and present. Setting judgment aside for a moment lets you meet the original face that exists prior to all evaluation.", "insight": "Beneath every judgment of good and evil lies the original, unconditioned nature of the self."},
  "法眼和尚、齋前指簾。時有二僧、同去捲簾。眼云、一得一失。": {"reflection": "Two people can perform the very same action with entirely different inner states. The quality of presence you bring to a task, not the act itself, decides whether it gains or loses.", "insight": "The merit of an action lies in the mind behind it, not in the identical outward deed."},
  "德山作禮出門。外面黑。卻回云、外面黑。龍潭點紙燭度與。山擬接。潭便吹滅。山於此忽然有省。": {"reflection": "We reach for borrowed light to navigate our darkness, but the lamp another hands us is blown out at the crucial moment. Real understanding dawns only when you stop depending on external lights.", "insight": "Awakening comes not from borrowed illumination but when one is thrown back upon one's own seeing."},
  "趙州因僧問、如何是祖師西來意。州云、庭前柏樹子。": {"reflection": "When you grasp for the hidden meaning behind everything, Joshu points you back to the plain oak tree in front of you. Truth is not stored elsewhere; it is in the ordinary thing already before your eyes.", "insight": "Ultimate reality is not abstract or distant but fully present in concrete, everyday things."},
  "五祖云、譬如水牛過窗櫺、頭角四蹄都過了、因甚麼尾巴過不得。": {"reflection": "You can change everything about your life and still feel one small thing holding you back. Often the last 'tail' is the part of yourself you refuse to examine, not an outer obstacle.", "insight": "What blocks final liberation is usually the subtle remnant of self-clinging, not any external barrier."},
  "赤肉團上有一無位真人、常從汝等諸人面門出入。未證據者看看。": {"reflection": "Your true self does not depend on your title, role, or status; it speaks through your eyes and words all day long. Stop chasing rank and simply notice the one already living and acting through you.", "insight": "The authentic self has no rank or label and is directly knowable in ordinary awareness."},
  "達磨面壁。二祖立雪斷臂云、弟子心未安、乞師安心。磨云、將心來、與汝安。祖云、覓心了不可得。磨云、為汝安心竟。": {"reflection": "When anxiety grips you, you search for 'my troubled mind' to fix it and cannot actually find such a fixed thing. The moment you look directly for it and grasp nothing, the restlessness has nowhere to stand.", "insight": "The suffering self cannot be located as a real object; seeing this directly is itself the peace we sought."},
  "石霜和尚云、百尺竿頭如何進步。又古德云、百尺竿頭坐的人、雖然得入未為真。百尺竿頭須進步、十方世界是全身。": {"reflection": "Even hard-won spiritual attainment can become a comfortable perch you cling to. Real maturity means stepping beyond your own achievement back into the whole world, holding nothing in reserve.", "insight": "True realization is not a final summit to rest on but a release that re-engages the entire world."},
  "趙州示眾云、至道無難、唯嫌揀擇。纔有語言、是揀擇是明白。老僧不在明白裏。是汝還護惜也無。時有僧問、既不在明白裏、護惜箇什麼。州云、我亦不知。": {"reflection": "Constantly sorting life into preferred and rejected keeps you tense and divided. Joshu even refuses to cling to his own 'clarity,' showing a freedom that holds no position to defend.", "insight": "The Way opens when we stop clutching preferences and even release our attachment to being right."},
  "雲門垂語云、十五日已前不問汝、十五日已後道將一句來。自代云、日日是好日。": {"reflection": "Stop weighing the past you cannot change and the future you cannot control. Met fully and without judgment, this very day, whatever it holds, is already a good day.", "insight": "Wholehearted acceptance of the present moment makes every day, as it is, complete and good."},
  "僧問雲門。如何是一代時教。門云。對一說。": {"reflection": "All the teaching you long for is not a vast doctrine to master but the one fitting word for this exact situation. Respond truly to what is in front of you and the whole teaching is fulfilled.", "insight": "The entire teaching reduces to meeting each moment with the response it actually calls for."},
  "洞山云。何不向無寒暑處去。": {"reflection": "We waste energy trying to dodge discomfort. Tozan shows another way: enter the cold completely as cold, the heat completely as heat, so fully that no separate sufferer is left standing apart from it.", "insight": "Freedom from suffering comes not by escaping conditions but by meeting them so totally that no resisting self remains."},
  "雲門示眾云。人人盡有光明在。看時不見暗昏昏。作麼生是諸人光明。自代云。廚庫三門。": {"reflection": "When you strain to find your inner light, it seems to vanish into darkness. Ummon answers that it was never hidden: it shines as the pantry and the gate, the plain things you live among.", "insight": "Our innate luminosity cannot be seized by introspection because it is already shining as ordinary life itself."},
  "諸仏如来、ともに妙法を伝えて阿耨多羅三藐三菩提を証するに、最上無為の妙術あり。これただ仏にのみうけてよこしまなることなきは、自受用三昧をその標準とせり。": {"reflection": "The deepest practice is not a technique you perform to gain a reward, but a settled, undivided absorption that is its own fulfillment. Sit and act for the wholeness of the act, not for what it earns.", "insight": "The highest practice is unconditioned and self-fulfilling, complete in itself rather than a means to a further goal."},
  "悉有の衆生は、ことごとく仏性なり": {"reflection": "You do not have to earn or import your worth from outside; your very being is already Buddha-nature. Treat yourself and every living thing as already carrying this dignity, not as a project to be perfected.", "insight": "Awakened nature is not a potential to be achieved but the actual substance of all beings as they are."},
  "竺土大仙心、東西密相付。人根有利鈍、道無南北祖。": {"reflection": "People differ in sharpness and circumstance, but the truth itself plays no favorites and belongs to no faction. Don't rank yourself above or below others on the path; the Way is whole for everyone who walks it.", "insight": "The Way transcends all human divisions of talent, lineage, and region; it is one and impartial."},
  "世尊一日陞座。文殊白椎云。諦觀法王法。法王法如是。世尊便下座。": {"reflection": "The deepest teaching may need no lecture at all. Sometimes the most honest response is to simply show up fully, let the moment speak as it is, and not pile words onto what is already complete.", "insight": "The highest truth is shown by direct presence rather than explained, for reality already declares itself."},
  "一句語須具三玄門、一玄門須具三要。有權有實、有照有用。汝等諸人作麼生會。": {"reflection": "A single true word can carry many layers at once: skillful adaptation and plain reality, clear seeing and living action. Speak and act so your one response meets the whole situation, not just its surface.", "insight": "Genuine expression is multidimensional, uniting insight and function, the practical and the real, in one act."},
  "閑さや岩にしみ入る蝉の声": {"reflection": "Notice how a single sharp sound can deepen rather than break the quiet around it. When you stop fighting the noise of life, even it can carry you into a stillness that absorbs everything.", "insight": "True stillness is not the absence of sound but a depth so vast that all things sink into it."},
  "鐘消えて花の香は撞く夕哉": {"reflection": "When one experience ends, its presence can carry on transformed in another. Let what fades nourish what remains, so the bell you can no longer hear keeps ringing in the scent of the evening flowers.", "insight": "Nothing simply vanishes; experience flows continuously, one form quietly carrying into the next."},
  "柿くへば鐘が鳴るなり法隆寺": {"reflection": "A simple, fully-tasted bite and a distant temple bell belong to one unbroken moment. When you give your whole attention to the ordinary, the sacred is not elsewhere; it sounds right through it.", "insight": "The sacred and the everyday are not two; full presence to one reveals the other within it."},
  "分け入っても分け入っても青い山": {"reflection": "However far you advance through a problem or a life, the horizon keeps receding. Walk on anyway — the path itself, not a final summit, is what you are given to inhabit.", "insight": "There is no arrival that ends the journey; the way is endless, and that is its truth, not its failure."},
  "善人なおもて往生をとぐ、いわんや悪人をや。": {"reflection": "Stop ranking yourself by your virtue before you ask for grace. The one who knows he cannot save himself is closest to receiving help, because he has stopped relying on his own merit.", "insight": "Grace meets those who have given up on self-power; awareness of one's own inadequacy opens the door, not personal righteousness."},
  "मात्रास्पर्शास्तु कौन्तेय शीतोष्णसुखदुःखदाः । आगमापायिनोऽनित्यास्तांस्तितिक्षस्व भारत ॥": {"reflection": "Heat and cold, pleasure and pain all arise where the senses meet the world, and all of them pass. When discomfort comes, learn to endure it, knowing it is temporary and not the whole of you.", "insight": "Sensory experiences are transient arrivals and departures; equanimity comes from not mistaking the passing for the permanent."},
  "जातस्य हि ध्रुवो मृत्युर्ध्रुवं जन्म मृतस्य च। तस्मादपरिहार्येऽर्थे न त्वं शोचितुमर्हसि।।": {"reflection": "Death for the born is as certain as anything can be. To grieve endlessly over what cannot be avoided only adds suffering; meet the unavoidable with steadiness rather than despair.", "insight": "Sorrow over the inevitable is wasted; clarity about life's certainties frees us from needless lament."},
  "ध्यायतो विषयान्पुंसः सङ्गस्तेषूपजायते । सङ्गात्सञ्जायते कामः कामात्क्रोधोऽभिजायते ॥": {"reflection": "Notice how dwelling on something you want quietly turns into attachment, then craving, then anger when it is blocked. The chain begins in the mind's lingering — watch where your attention rests.", "insight": "Anger is not sudden; it grows by stages from the simple act of brooding on what we desire."},
  "क्रोधाद्भवति सम्मोहः सम्मोहात्स्मृतिविभ्रमः । स्मृतिभ्रंशाद्बुद्धिनाशो बुद्धिनाशात्प्रणश्यति ॥": {"reflection": "Anger clouds judgment, then you forget what you know, then reason fails entirely and you act in ways that undo you. Catch the anger early, before it dismantles your clarity step by step.", "insight": "Unchecked anger destroys through a cascade — delusion, lost memory, ruined reason — ending in self-undoing."},
  "या निशा सर्वभूतानां तस्यां जागर्ति संयमी । यस्यां जाग्रति भूतानि सा निशा पश्यतो मुनेः ॥": {"reflection": "What most people stay awake for, the wise treat as sleep; what most ignore, the wise attend to. Examine whether your daily striving is truly worth your waking hours.", "insight": "The sage and the crowd are awake to opposite things; wisdom reverses the ordinary scale of what deserves attention."},
  "ये यथा मां प्रपद्यन्ते तांस्तथैव भजाम्यहम्। मम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः।।": {"reflection": "The spirit in which you approach the divine is the spirit in which it answers you. How you turn toward it shapes how it meets you in return.", "insight": "We are met according to the manner of our own approach; reciprocity, not favoritism, governs the response."},
  "तद्विद्धि प्रणिपातेन परिप्रश्नेन सेवया । उपदेक्ष्यन्ति ते ज्ञानं ज्ञानिनस्तत्त्वदर्शिनः ॥": {"reflection": "Real understanding is not seized but received — through humility, honest questioning, and service to those who have actually realized the truth. Approach learning with respect, not demand.", "insight": "Knowledge is transmitted to the humble and serving inquirer, not extracted by the proud."},
  "न हि ज्ञानेन सदृशं पवित्रमिह विद्यते। तत्स्वयं योगसंसिद्धः कालेनात्मनि विन्दति।।": {"reflection": "Nothing purifies like genuine understanding, and it cannot be rushed. Practice steadily, and in time the knowledge ripens within you of its own accord rather than being grasped from outside.", "insight": "True knowledge is the purest thing there is, and it matures inwardly through patient practice over time."},
  "बन्धुरात्मात्मनस्तस्य येनात्मैवात्मना जितः। अनात्मनस्तु शत्रुत्वे वर्तेतात्मैव शत्रुवत्।।": {"reflection": "Your own mind is either your closest ally or your worst adversary, and which one depends on whether you have mastered it. The same self can lift you up or drag you down.", "insight": "The mind becomes friend or enemy by our own discipline; the decisive battle is the one we wage with ourselves."},
  "सर्वभूतस्थमात्मानं सर्वभूतानि चात्मनि। ईक्षते योगयुक्तात्मा सर्वत्र समदर्शनः।।": {"reflection": "When you are inwardly steady, you begin to see the same essence in yourself and in everyone else. That shared seeing dissolves the impulse to divide people into worthy and unworthy.", "insight": "Equal vision flows from inner union — recognizing one self present in all beings and all beings within the self."},
  "तस्मात्सर्वेषु कालेषु मामनुस्मर युध्य च । मय्यर्पितमनोबुद्धिर्मामेवैष्यस्यसंशयः ॥": {"reflection": "You do not have to abandon your duties to live a spiritual life. Keep doing your work while holding the divine steadily in mind; remembrance and action belong together.", "insight": "The sacred and the practical are not rivals — devotion is sustained through engaged action, not withdrawal from it."},
  "पत्रं पुष्पं फलं तोयं यो मे भक्त्या प्रयच्छति । तदहं भक्त्युपहृतमश्नामि प्रयतात्मनः ॥": {"reflection": "What you offer matters far less than the love behind it. A leaf or a cup of water given with a sincere heart is received fully — devotion, not extravagance, is what counts.", "insight": "The divine measures the offering by its love and purity of heart, not by its material worth."},
  "यत्करोषि यदश्नासि यज्जुहोषि ददासि यत्। यत्तपस्यसि कौन्तेय तत्कुरुष्व मदर्पणम्॥": {"reflection": "Your eating, working, giving, and effort can all become sacred when offered with the right intention. Daily life itself becomes worship when each act is dedicated beyond yourself.", "insight": "Any ordinary action turns into an offering when consciously dedicated to the divine."},
  "अपि चेत्सुदुराचारो भजते मामनन्यभाक् । साधुरेव स मन्तव्यः सम्यग्व्यवसितो हि सः ॥": {"reflection": "Even someone with a deeply flawed past who turns wholeheartedly toward the divine has set himself rightly. Honor the sincerity of the change rather than holding the old life against him.", "insight": "Wholehearted right resolve redeems a person; sincere reorientation, not a spotless past, defines the seeker."},
  "यद्यद्विभूतिमत्सत्त्वं श्रीमदूर्जितमेव वा । तत्तदेवावगच्छ त्वं मम तेजोंऽशसम्भवम् ॥": {"reflection": "Whatever is powerful, beautiful, or glorious that you admire is only a small spark of a far greater splendor. Let excellence point you beyond itself rather than become an idol.", "insight": "All worldly magnificence is a fragment of the divine radiance, a pointer to its source, not the source itself."},
  "यस्मान्नोद्विजते लोको लोकान्नोद्विजते च यः। हर्षामर्षभयोद्वेगैर्मुक्तो यः स च मे प्रियः॥": {"reflection": "Aim to be someone whom others are not anxious around and who is not anxious around others — free from outbursts of elation, resentment, and fear. Such steadiness is a quiet gift to everyone near you.", "insight": "True belovedness lies in causing no agitation and feeling none, resting beyond the swings of emotion."},
  "श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात् । स्वभावनियतं कर्म कुर्वन्नाप्नोति किल्बिषम् ॥": {"reflection": "Doing your own honest work imperfectly serves you better than copying someone else's path flawlessly. Stay true to the duties your own nature and circumstances set before you, and you carry no guilt.", "insight": "Authenticity in one's own calling outweighs the polished imitation of another's."},
  "इदं खलु पुनर् भिक्षवो दुःखमार्यसत्यम्। जातिरपि दुःखा जरापि दुःखा व्याधिरपि दुःखो मरणमपि दुःखम्...": {"reflection": "Aging, sickness, loss, and not getting what you want are not failures to fix but the shared texture of life. Naming this honestly, instead of denying it, is where real freedom begins.", "insight": "Suffering is woven into existence itself, and seeing it clearly is the first step toward release."},
  "रूपं भिक्षवोऽनात्मा। रूपं चेदिदं भिक्षव आत्माऽभविष्यत्, नेदं रूपमाबाधाय समवर्तिष्यत...": {"reflection": "Your body ages and falls ill no matter how firmly you command it otherwise, proof that it is not truly 'you.' Loosening your grip on identifying with the body eases much of its suffering.", "insight": "What we cannot finally control cannot be the self we take it to be."},
  "एत यूयं कालामाः, मा अनुश्रवेण, मा परम्परया, मा इतिकिरया, मा पिटकसम्पदानेन...": {"reflection": "Do not accept a claim just because it is old, popular, written down, or spoken by an impressive voice. Test teachings against your own honest experience before you let them guide your life.", "insight": "Genuine conviction must be earned through inquiry, not borrowed from authority or tradition."},
  "मनःपूर्वाङ्गमा धर्मा मनःश्रेष्ठा मनोमयाः। मनसा चेत् प्रसन्नेन भाषते वा करोति वा। ततस्तं सुखमन्वेति छायेवानपायिनी॥": {"reflection": "Every word and deed begins in the mind, so tending your inner state is the most practical work you can do. Act and speak from a clear, kind mind, and contentment follows you like your own shadow.", "insight": "The quality of the mind shapes the quality of all that flows from it."},
  "अनेकजातिसंसारं संधाविष्यमनिविशम्। गृहकारकमेषन्तो दुःखा जातिः पुनः पुनः॥": {"reflection": "We spend lifetimes chasing the very craving that keeps rebuilding our suffering. Recognizing what constructs our cycles of pain is the first step toward not laying those bricks again.", "insight": "The ceaseless searching itself feeds the cycle until its hidden builder is seen."},
  "सर्वदानं धर्मदानं जिनाति सर्वरसं धर्मरसो जिनाति। सर्वरतिं धर्मरतिर्जिनाति तृष्णाक्षयः सर्वदुःखं जिनाति॥": {"reflection": "Sharing truth and wisdom outlasts any material gift, and its joy outlasts every passing pleasure. Above all, freeing yourself from grasping craving is the one victory over suffering itself.", "insight": "The deepest giving is wisdom, and the deepest peace is the end of craving."},
  "तद्यथापि मालुक्यपुत्र पुरुषः शल्येन विद्धः स्यात् सविषेण गाढप्रलेपनेन...": {"reflection": "Endless speculation about questions that do not heal you is like refusing the surgeon until you know the archer's caste. Attend first to the wound that is actually causing your pain.", "insight": "Liberation comes from removing suffering, not from answering every abstract question first."},
  "कोलुपमं वो भिक्षवो धर्मं देशयिष्यामि निस्तरणार्थाय, नो ग्रहणार्थाय।": {"reflection": "Teachings, methods, and even beliefs are a raft to carry you across, not a load to clutch forever. Use what helps you grow, and hold it lightly enough to set it down once it has served.", "insight": "Even the truest teaching is a means to cross over, never a possession to cling to."},
  "अस्मिन् सतीदं भवति, अस्योत्पादादिदमुत्पद्यते। अस्मिन् असतीदं न भवति, अस्य निरोधादिदं निरुध्यते।": {"reflection": "Nothing in your life arises alone; conditions give rise to conditions, and removing a cause removes its effect. Trace what feeds a habit or hurt, and you find where it can finally end.", "insight": "All things arise and cease through conditions, so changing causes changes outcomes."},
  "तत् किं मन्यध्वे भिक्षवः, कतमत् नु खलु बहुतरम्, यद् वा वः अनेन दीर्घेण अध्वना संधावतां संसरताम्... अश्रु प्रस्यन्नं प्रक्षरितम्, या वा चतुर्षु महासमुद्रेषु आपः?": {"reflection": "The tears already shed over loss and parting outnumber the waters of the oceans. Letting this sink in moves us to seek a way out of endless grasping rather than repeating the same griefs.", "insight": "The sheer immensity of accumulated sorrow is itself a call to seek release."},
  "त्रिधातुकमिदं सर्वमादीप्तं गृहसन्निभम्।": {"reflection": "No corner of worldly life offers lasting safety from birth, aging, sickness, and death. Seeing this clearly is not despair but the urgency to walk calmly toward the door of real freedom.", "insight": "Recognizing the impermanence of all conditioned existence awakens the urgency to seek what endures."},
  "या सर्वधर्माणामनभिलाप्यता अविज्ञप्तिरप्रकाशना अनिदर्शना अकथिता, अयमुच्यतेऽद्वयधर्मपर्यायप्रवेशः।": {"reflection": "Some truths are entered through silence, not by naming, explaining, or arguing them into shape. There are moments when the wisest response is to stop fixing and labeling, and simply be present.", "insight": "The deepest reality lies beyond words and concepts, entered only by letting go of designation."},
  "चित्तं चित्रकरसदृशं सर्वलोकं विरचयति। पञ्चस्कन्धाः ततः जाताः न तदस्ति यन्न निर्मितम्॥": {"reflection": "Like a painter, your mind colors the whole world you experience. Noticing how much of your reality is your own mind's brushwork lets you paint with more care and less reactivity.", "insight": "The world we inhabit is largely the creation of our own perceiving mind."},
  "अनाथानामहं नाथः सार्थवाहश्च यायिनाम् । पारमिच्छतां नौश्च सेतुः सङ्क्रम एव च ॥": {"reflection": "Aspire to be shelter for the unprotected and a guide for those who have lost their way. Make yourself a bridge others can cross on, offering your strength wherever someone needs to get through.", "insight": "A life of meaning is one given over to becoming refuge and passage for others."},
  "ये केचिज्जगत्यानन्दास्ते सर्वेऽन्यसुखेच्छया । ये केचिज्जगती दुःखास्ते सर्वे स्वसुखेच्छया ॥": {"reflection": "Trace your happiest moments and you will often find concern for others behind them; trace your misery and you will often find a self chasing its own comfort. Turn your wishes outward.", "insight": "Joy grows from wishing others well, while suffering grows from seeking only one's own pleasure."},
  "न तन्माता पिता कुर्यादन्ये वापि च ज्ञातयः । सम्यक्प्रणिहितं चित्तं श्रेयो वै तत आचरेत् ॥": {"reflection": "No one, however loving, can do for you what your own well-directed mind can. Train your attention toward what is good, for that inner discipline serves you beyond any outside help.", "insight": "A rightly directed mind benefits a person more than even the most devoted family can."},
  "दिवा तपति आदित्यो रात्रावाभाति चन्द्रमाः । संनद्धः क्षत्रियस्तपति ध्यायी तपति ब्राह्मणः । अथ सर्वमहोरात्रं बुद्धस्तपति तेजसा ॥": {"reflection": "Sun, moon, warrior, and sage each shine in their own time and setting. An awakened mind, steady and bright through every condition, reminds us that inner clarity does not flicker with circumstance.", "insight": "True radiance is the steady inner light that shines regardless of time or circumstance."},
  "प्रभास्वरमिदं भिक्षवश्चित्तम् । तच्च खल्वागन्तुकैरुपक्लेशैरुपक्लिष्टम् ।": {"reflection": "Your anger or anxiety today is not who you are; it is a passing visitor settling on a mind that is clear underneath. Notice the cloud without mistaking it for the sky.", "insight": "Defilements are adventitious arrivals, not the mind's intrinsic nature, which remains luminous."},
  "即心是佛": {"reflection": "Stop searching elsewhere for peace or worth. The awakened nature you seek is already this present mind; quiet the constant commentary and it shows itself.", "insight": "Awakening is not attained from outside but is the very mind freed from conceptual proliferation."},
  "拈花微笑": {"reflection": "Some understanding passes wordlessly between people who are truly present. When a friend simply holds up a moment, meet it with attention rather than explanation.", "insight": "The deepest transmission is direct and silent, beyond what words can carry."},
  "不昧因果": {"reflection": "Even the wise stay clear-eyed about consequences. Don't pretend your choices float free of their results; act knowing each deed quietly shapes what comes next.", "insight": "Realization does not exempt anyone from cause and effect but makes one fully awake to it."},
  "庭前柏樹子": {"reflection": "When you ask the big questions, the answer may be the ordinary thing right in front of you. Attend to the tree, the cup, the breath, instead of chasing the abstract.", "insight": "Ultimate meaning is not hidden elsewhere but present in the plainest immediate thing."},
  "日日是好日": {"reflection": "Not every day is easy, yet each one can be met as good when you stop ranking it against some better day. Receive today fully, exactly as it arrives.", "insight": "Goodness lies in wholehearted presence to each day rather than in favorable circumstances."},
  "逢佛殺佛，逢祖殺祖": {"reflection": "Don't turn teachers or ideals into idols you cling to. When you make even a holy image into a crutch, set it down and stand on your own direct experience.", "insight": "Genuine freedom requires releasing attachment to every authority and concept, however revered."},
  "赤肉團上有一無位真人": {"reflection": "Beneath your titles, roles, and reputation lives the one who simply is, owing its worth to no rank. Meet people, and yourself, from that placeless dignity.", "insight": "The true self is prior to all social rank and identity, dwelling in this very body."},
  "百尺竿頭に一歩を進む": {"reflection": "Even at the summit of your effort, growth asks one more step into the unknown. Don't cling to the achievement you've reached; let go and move beyond it.", "insight": "Real progress demands releasing the very attainment one is standing on."},
  "坐禅は習禅にはあらず。唯是れ安楽の法門なり。": {"reflection": "Sitting quietly is not a skill to master or a performance to grade. Approach stillness as rest and ease, not one more task to achieve.", "insight": "Meditation is not technique to be acquired but a gateway of natural repose and ease."},
  "生死すなわち涅槃": {"reflection": "You need not escape ordinary life to find peace. The very flow of changing, aging, and letting go is where liberation is found, not somewhere beyond it.", "insight": "Liberation is not apart from birth-and-death but realized within it."},
  "非思量": {"reflection": "When the mind races, don't fight thought or force blankness. Rest in an open awareness that neither grasps thoughts nor suppresses them, simply letting them pass.", "insight": "True stillness is non-thinking, an alert awareness beyond both grasping and suppression."},
  "明暗各相對，比如前後步": {"reflection": "Ease and difficulty, clarity and confusion, alternate like your two feet while walking. Neither is the enemy; together they carry you forward.", "insight": "Opposites are interdependent partners in a single movement, not contradictions to eliminate."},
  "理入者：謂藉教悟宗，深信含生同一真性": {"reflection": "Let teaching point you past itself to a quiet conviction: every living being shares one true nature. Treat the stranger as kin to that same depth in you.", "insight": "Understanding through instruction culminates in faith that all beings share one true nature."},
  "無明實性即佛性，幻化空身即法身": {"reflection": "Don't despise your confusion or your fragile body as obstacles to overcome. Rightly seen, the very ignorance and impermanence you carry are the ground of awakening.", "insight": "Delusion and the transient body are not other than Buddha-nature and the Dharma-body."},
  "善人なおもて往生をとぐ、いわんや悪人をや": {"reflection": "If you feel unworthy because of your failings, this is precisely the one grace welcomes most. Stop disqualifying yourself; humility, not merit, opens the door.", "insight": "Grace embraces the flawed most fully, for it rests on compassion rather than earned merit."},
  "至道無難，唯嫌揀擇": {"reflection": "Much of your inner struggle comes from constant judging, this is good, that is bad. Loosen the reflex to pick sides and a natural clarity returns on its own.", "insight": "The way becomes difficult only through compulsive preference; truth appears when judging relaxes."},
  "भीम रूप धरि असुर संहारे। रामचंद्र के काज सँवारे॥": {"reflection": "When a worthy purpose calls, rise to your full size. The verse honors strength used not for self but to serve another's mission, completing the work entrusted to you.", "insight": "True power finds its meaning when placed in service of a cause greater than oneself."},
  "सहस बदन तुम्हरो जस गावैं। अस कहि श्रीपति कंठ लगावैं॥": {"reflection": "The greatest recognition comes not from crowds but from the one you faithfully served. Devotion done quietly draws the embrace of the beloved.", "insight": "Sincere service is honored most intimately by the one for whom it was offered."},
  "जम कुबेर दिगपाल जहाँ ते। कबि कोबिद कहि सके कहाँ ते॥": {"reflection": "Some greatness exceeds every attempt to capture it in words. Hold humility before what is too vast for even the wise to fully describe.", "insight": "The truly great surpasses all our measures, descriptions, and comprehension."},
  "तुम उपकार सुग्रीवहिं कीन्हा। राम मिलाय राज पद दीन्हा॥": {"reflection": "The deepest help you can give another is to connect them with what restores their dignity and rightful place. Lift others not by pity but by opening a door.", "insight": "Genuine kindness empowers another to recover what is rightfully theirs."},
  "प्रभु चरित्र सुनिबे को रसिया। राम लखन सीता मन बसिया॥": {"reflection": "What we delight in hearing slowly takes residence in the heart. Fill your attention with what is good, and it will come to dwell within you.", "insight": "What we love to dwell upon becomes the lasting inhabitant of the heart."},
  "आपन तेज सम्हारो आपै। तीनों लोक हाँक तें काँपै॥": {"reflection": "Real strength is shown not in unleashing power but in restraining it. The one who can shake worlds yet holds himself in check models mastery over force.", "insight": "The mark of true power is the capacity to govern one's own immense strength."},
  "नासै रोग हरै सब पीरा। जपत निरंतर हनुमत बीरा॥": {"reflection": "Steady, repeated remembrance steadies the mind and eases suffering. A constant inner anchor carries us through pain and restlessness.", "insight": "Persistent devotional remembrance brings relief to both body and troubled mind."},
  "और मनोरथ जो कोई लावै। सोइ अमित जीवन फल पावै॥": {"reflection": "Bring your honest longings before what you hold sacred rather than carrying them alone. Sincere desire offered with trust bears fruit beyond reckoning.", "insight": "Desires entrusted in faith yield a fulfillment beyond their original measure."},
  "दुर्गम काज जगत के जेते। सुगम अनुग्रह तुम्हरे तेते॥": {"reflection": "Tasks that seem impossible alone grow lighter when grace meets effort. Face the difficult work, but do not assume you carry it by your strength alone.", "insight": "Grace transforms the seemingly insurmountable into the achievable."},
  "राम दुआरे तुम रखवारे। होत न आज्ञा बिनु पैसारे॥": {"reflection": "There is dignity in faithfully guarding the threshold entrusted to you. To stand watch with integrity is itself a sacred office.", "insight": "Faithful guardianship of what is entrusted is honored as much as great deeds."},
  "भूत पिसाच निकट नहिं आवै। महाबीर जब नाम सुनावै॥": {"reflection": "When the mind holds onto courage and the sacred, fear and dark imaginings lose their grip. A steady remembrance keeps the troubling at a distance.", "insight": "Holding the mind on courage and the sacred dispels the fears that haunt it."},
  "सब पर राम तपस्वी राजा। तिन के काज सकल तुम साजा॥": {"reflection": "Aligning your work under a higher principle gives every task coherence and worth. Serve something true above you, and your efforts find their order.", "insight": "Work gains its fullness when ordered toward and accomplished for a higher truth."},
  "संकट कटै मिटै सब पीरा। जो सुमिरै हनुमत बलबीरा॥": {"reflection": "In crisis, returning the mind to a source of strength loosens panic's hold. Remembrance does not erase trouble but steadies us to meet it.", "insight": "Turning the mind toward strength in adversity dissolves crisis and eases pain."},
  "राम रसायन तुम्हरे पासा। सदा रहो रघुपति के दासा॥": {"reflection": "The deepest medicine is a life devoted to what is true, held in the posture of glad service. To remain a willing servant is itself the remedy.", "insight": "A life of steady devotional service is itself the elixir that heals."},
  "और देवता चित्त न धरई। हनुमत सेइ सर्ब सुख करई॥": {"reflection": "A heart settled in single-minded devotion finds contentment without scattering itself in every direction. Wholeness comes from focused, faithful attention.", "insight": "Undivided devotion to one true thing brings a completeness that scattered seeking cannot."},
  "न हि वेरेन वेरानि, सम्मन्तीध कुदाचनं।": {"reflection": "Returning anger for anger only deepens the wound; the cycle ends only when one side refuses to repay hatred. Meet hostility with non-hatred to break the chain.", "insight": "Hatred is never quenched by hatred, only ever by its opposite — this is eternal law."},
  "अष्ट सिद्धि नौ निधि के दाता। अस बर दीन जानकी माता॥": {"reflection": "The deepest gifts are entrusted to those proven faithful in service. Capacity to bless others is itself something granted, not seized.", "insight": "The power to give to others is a boon earned through faithful devotion."},
  "अन्त काल रघुबर पुर जाई। जहाँ जन्म हरि-भक्त कहाई॥": {"reflection": "A life oriented toward the sacred carries that orientation to its very end and beyond. How we live shapes the destination toward which we move.", "insight": "A life devoted to the divine carries its devotion through death and into whatever follows."},
  "यो च वस्ससतं जीवे, अपस्सं उदयब्बयं।": {"reflection": "A single day spent truly noticing how things arise and pass — a mood, a relationship, a season of life — teaches more than decades of living on autopilot. Watch impermanence today rather than fearing it.", "insight": "Awareness of change is wisdom; mere duration of life without insight is empty."},
  "अशोच्यानन्वशोचस्त्वं प्रज्ञावादांश्च भाषसे। गतासूनगतासूंश्च नानुशोचन्ति पण्डिताः॥": {"reflection": "We often grieve where grief isn't warranted and dress our anxiety in clever reasons. Pause and ask whether your sorrow rests on a true loss or on a misunderstanding of what truly endures.", "insight": "The wise do not mourn for what is imperishable; clarity dissolves needless grief."},
  "श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात्। स्वधर्मे निधनं श्रेयः परधर्मो भयावहः॥": {"reflection": "Doing your own honest work imperfectly is better than flawlessly imitating someone else's life. Honour the duty and nature that are genuinely yours rather than chasing a borrowed path.", "insight": "Fidelity to one's own calling, even flawed, is safer than perfection in another's role."},
  "एवमुक्त्वार्जुनः सङ्ख्ये रथोपस्थ उपाविशत्। विसृज्य सशरं चापं शोकसंविग्नमानसः॥": {"reflection": "Even the strongest can be overwhelmed and lay down their tools, mind flooded with grief. There is no shame in such a collapse — it is often the honest beginning of seeking real guidance.", "insight": "The crisis where capability fails and grief takes over can become the doorway to deeper teaching."},
  "भोक्तारं यज्ञतपसां सर्वलोकमहेश्वरम्। सुहृदं सर्वभूतानां ज्ञात्वा मां शान्तिमृच्छति॥": {"reflection": "Peace comes from knowing the Divine as the true recipient of all our effort and the genuine well-wisher of every being. Offer your work upward and trust that friendship behind all things.", "insight": "Peace arises from recognizing the Lord as the friend and ultimate purpose of all our striving."},
  "संकर सुवन केसरीनंदन। तेज प्रताप महा जग बंदन॥": {"reflection": "Hanuman's strength is honoured by the whole world because it serves something higher than itself. Let your own energy and ability gain dignity by being placed in devoted service.", "insight": "True majesty is power revered because it is wielded in humble, sacred service."},
  "यं यं वापि स्मरन्भावं त्यजत्यन्ते कलेवरम्। तं तमेवैति कौन्तेय सदा तद्भावभावितः॥": {"reflection": "What fills your mind at the end is shaped by what you dwell on throughout life. Tend your daily thoughts carefully, for they quietly become the direction of your whole being.", "insight": "The mind's habitual focus determines its final destination; remembrance shapes destiny."},
  "बहूनां जन्मनामन्ते ज्ञानवान्मां प्रपद्यते। वासुदेवः सर्वमिति स महात्मा सुदुर्लभः॥": {"reflection": "Recognizing the Divine in everything is the fruit of long maturation, not a quick win. Be patient with your spiritual growth; such surrender ripens over time and is precious when it comes.", "insight": "Seeing the Divine as the source of all is the rare culmination of many lives of seeking."},
  "यत्र योगेश्वरः कृष्णो यत्र पार्थो धनुर्धरः । तत्र श्रीर्विजयो भूतिर्ध्रुवा नीतिर्मतिर्मम ॥": {"reflection": "Lasting success needs both divine guidance and skilled, willing effort working together. Pair your honest work with surrender to a higher wisdom, and prosperity rests on a firm moral footing.", "insight": "Where divine wisdom and disciplined human effort unite, success and righteousness endure together."},
  "यद्यदाचरति श्रेष्ठस्तत्तदेवेतरो जनः। स यत्प्रमाणं कुरुते लोकस्तदनुवर्तते॥": {"reflection": "Whoever others look up to is teaching constantly through example, not words. As a parent, leader, or elder, remember that your conduct sets a standard people quietly follow.", "insight": "The respected person leads chiefly by example; their actions become the standard others adopt."},
  "उद्धरेदात्मनात्मानं नात्मानमवसादयेत्। आत्मैव ह्यात्मनो बन्धुरात्मैव रिपुरात्मनः॥": {"reflection": "Your own mind can lift you up or drag you down — no one else holds that power. Choose to befriend yourself through disciplined thought rather than becoming your own worst adversary.", "insight": "The trained mind is one's greatest ally; the unchecked mind, one's own enemy."},
  "यत्रोपरमते चित्तं निरुद्धं योगसेवया। यत्र चैवात्मनात्मानं पश्यन्नात्मनि तुष्यति॥": {"reflection": "When the restless mind finally grows still through steady practice, contentment is found within rather than chased outside. Cultivate quiet, and you discover a joy that needs nothing external.", "insight": "A mind stilled by practice perceives the Self and finds lasting joy within, not in objects."},
  "श्रीभगवानुवाच । ऊर्ध्वमूलमधःशाखमश्वत्थं प्राहुरव्ययम् । छन्दांसि यस्य पर्णानि यस्तं वेद स वेदवित् ॥": {"reflection": "Life is like a tree rooted in the unseen above, its visible branches reaching into our world. Understanding that our everyday existence draws from a higher source is the beginning of true knowledge.", "insight": "The visible world is rooted in an unseen reality; knowing this origin is genuine wisdom."},
  "雲門、因僧問、如何是佛。門云、乾屎橛。": {"reflection": "When asked about the highest, the master gave the lowliest answer to shatter the seeker's lofty ideas. Stop looking for the sacred only in grand places; it refuses to be cornered by your concepts.", "insight": "The ultimate cannot be captured by exalted concepts; awakening shatters our images of it."},
  "मया ततमिदं सर्वं जगदव्यक्तमूर्तिना। मत्स्थानि सर्वभूतानि न चाहं तेष्ववस्थितः॥": {"reflection": "The Divine pervades everything yet is never confined by anything. Take comfort that a vast unseen presence holds all beings, including you, without being limited by any of them.", "insight": "The Divine sustains all beings while transcending and never being contained by them."},
  "तेषां सततयुक्तानां भजतां प्रीतिपूर्वकम् । ददामि बुद्धियोगं तं येन मामुपयान्ति ते ॥": {"reflection": "Steady, loving devotion is met with inner guidance you could not manufacture alone. Keep showing up with sincerity, and the understanding needed to draw nearer will be given to you.", "insight": "Constant loving devotion is answered by grace that grants the very understanding to reach the Divine."},
  "मनोपुब्बङ्गमा धम्मा, मनोसेट्ठा मनोमया।": {"reflection": "Every word and deed is born first in the mind, so the quality of your thoughts shapes the quality of your life. Guard what you cultivate inwardly, for the outer world grows from it.", "insight": "Mind is the forerunner of all experience; inner states author our outer reality."},
  "भक्त्या त्वनन्यया शक्य अहमेवंविधोऽर्जुन । ज्ञातुं द्रष्टुं च तत्त्वेन प्रवेष्टुं च परन्तप ॥": {"reflection": "The deepest truths open not to cleverness but to wholehearted, undivided love. Approach what matters most with sincere devotion rather than mere analysis, and it reveals itself to you.", "insight": "Undivided devotion, not intellect alone, grants true knowledge and direct vision of the Divine."},
  "यः शास्त्रविधिमुत्सृज्य वर्तते कामकारतः । न स सिद्धिमवाप्नोति न सुखं न परां गतिम् ॥": {"reflection": "When you toss aside tested guidance and act purely on impulse, the wins feel free but rarely last. Lean on tried wisdom and discipline, and your effort actually compounds toward something real.", "insight": "Untethered desire cannot deliver lasting fulfillment; freedom matures only within a structure of wise restraint."},
  "सर्वयोनिषु कौन्तेय मूर्तयः सम्भवन्ति याः । तासां ब्रह्म महद्योनिरहं बीजप्रदः पिता ॥": {"reflection": "Every living being, in every form, shares one origin. Let that shrink the distance between you and others today, and soften how you treat even the creatures and people you'd overlook.", "insight": "A single divine source underlies all the world's diversity, making kinship the deepest truth of existence."},
  "श्रीभगवानुवाच । अभयं सत्त्वसंशुद्धिर्ज्ञानयोगव्यवस्थितिः । दानं दमश्च यज्ञश्च स्वाध्यायस्तप आर्जवम् ॥": {"reflection": "Good character is built deliberately: courage, honesty within, generosity, self-control, study, simplicity. Pick one of these qualities and practice it concretely today rather than waiting to feel virtuous.", "insight": "A noble nature is not innate temperament but a set of cultivable disciplines."},
  "अप्पमादो अमतपदं, पमादो मच्चुनो पदं।": {"reflection": "Drifting through the day half-asleep to your own choices is a quiet kind of dying. Bring full attention to this hour's work and words, and you become genuinely alive in it.", "insight": "Wakeful awareness is what separates a truly living life from mere mechanical existence."},
  "धर्मक्षेत्रे कुरुक्षेत्रे समवेता युयुत्सवः। मामकाः पाण्डवाश्चैव किमकुर्वत सञ्जय॥": {"reflection": "Notice the blind king's word 'mine' as he asks about the battlefield; attachment colors how he sees even his own kin. Watch where 'mine versus theirs' quietly distorts your own judgment of a conflict.", "insight": "Partiality born of attachment clouds clear sight before a single act is even taken."},
  "अत्तना व कतं पापं अत्तना सङ्किलिस्सति । अत्तना अकतं पापं अत्तना व विसुज्झति ॥": {"reflection": "No one can stain or cleanse your conscience for you. Stop waiting to be rescued or blamed by others; the next honest, decent choice that purifies you is entirely yours to make.", "insight": "Moral defilement and purity are self-authored; responsibility for one's inner state cannot be outsourced."},
  "सब्बपापस्स अकरणं कुसलस्स उपसम्पदा । सचित्तपरियोदपनं एतं बुद्धान सासनं ॥": {"reflection": "The whole path fits in three daily moves: do no harm, do some good, and quiet the mind. Before complicating your spiritual life, simply check today against these three.", "insight": "The essence of awakened teaching is ethical restraint, active good, and inner purification—not elaborate doctrine."},
  "सब्बे सङ्खारा अनिच्चाति यदा पञ्ञाय पस्सति । अथ निब्बिन्दती दुक्खे एस मग्गो विसुद्धिया ॥": {"reflection": "Everything you cling to is already changing. Seeing this clearly doesn't make you cold; it loosens the grip that hurts, freeing you to hold things gently while they last.", "insight": "Insight into impermanence dissolves the craving that turns ordinary change into suffering."},
  "मेघः समं मुञ्चति वारिधाराम् । ओषध्यो वृक्षगुल्माश्च यथाबलं तद्विभजन्ति वारि ॥": {"reflection": "The same rain falls on all, yet each plant takes what it can hold. Offer your help and teaching evenly, without resentment that people receive it differently—each absorbs according to their own readiness.", "insight": "Grace is given impartially, but its benefit is received in proportion to each one's capacity."},
  "एकायनो अयं भिक्खवे मग्गो सत्तानं विसुद्धिया सोकपरिदेवानं समतिक्कमाय दुक्खदोमनस्सानं अत्थङ्गमाय ञायस्स अधिगमाय निब्बानस्स सच्छिकिरियाय यदितिदां चत्तारो सतिपट्ठाना ॥": {"reflection": "When sorrow and grief feel overwhelming, the verse points to one steady remedy: returning attention again and again to body, feeling, mind, and reality as they are. Begin with simply noticing your breath.", "insight": "Sustained mindfulness is presented as the direct route through grief toward purification and peace."},
  "平常心是道。": {"reflection": "You don't need a special state or perfect setting to live rightly. The way reveals itself in washing dishes, answering a message, walking to work—in the ordinary mind meeting the ordinary moment.", "insight": "The sacred is not elsewhere; the everyday mind, met fully, is itself the path."},
  "कर्मण्येवाधिकारस्ते मा फलेषु कदाचन। मा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि॥": {"reflection": "Your job is the work itself, not control over how it turns out. Give your full effort today, then release your grip on the result—and don't let fear of outcomes tempt you into doing nothing.", "insight": "Freedom lies in wholehearted action surrendered from its fruits, between anxious grasping and paralyzed inaction."},
  "न परो परं निकुब्बेथ नातिमञ्ञेथ कत्थचि न कं चि । ब्यारोसना पटिघसञ्ञा नाञ्ञमञ्ञस्स दुक्खमिच्छेय्य ॥": {"reflection": "Don't deceive, don't look down on anyone, and when anger rises, refuse to wish another person harm. Let irritation pass through you today without turning into a quiet hope that someone suffers.", "insight": "Genuine goodwill means withholding not only harmful acts but even the inward wish for another's pain."},
  "मत्तः परतरं नान्यत्किञ्चिदस्ति धनञ्जय। मयि सर्वमिदं प्रोतं सूत्रे मणिगणा इव॥": {"reflection": "Like beads strung on a single thread, the scattered pieces of your life are held together by one underlying ground. When things feel fragmented, remember the unseen thread that quietly connects them all.", "insight": "A single divine reality threads through and unifies all the seemingly separate parts of existence."},
  "मच्चित्ता मद्गतप्राणा बोधयन्तः परस्परम् । कथयन्तश्च मां नित्यं तुष्यन्ति च रमन्ति च ॥": {"reflection": "Devotion deepens in good company. Seek out people who lift your mind toward what is highest, and offer the same in return—mutual encouragement turns shared faith into lasting joy.", "insight": "Spiritual fulfillment is nourished in fellowship, where devotees awaken and delight one another."},
  "ब्रह्मणो हि प्रतिष्ठाहममृतस्याव्ययस्य च । शाश्वतस्य च धर्मस्य सुखस्यैकान्तिकस्य च ॥": {"reflection": "Beneath the changing surface of your days rests something deathless and unshakeable. When circumstances tremble, you can root your sense of self in that abiding ground rather than the passing storm.", "insight": "Behind the impermanent stands an imperishable foundation that is the true seat of lasting happiness."},
  "क्षेत्रज्ञं चापि मां विद्धि सर्वक्षेत्रेषु भारत । क्षेत्रक्षेत्रज्ञयोर्ज्ञानं यत्तज्ज्ञानं मतं मम ॥": {"reflection": "You are not only the body and its conditions, but the awareness witnessing them. Practice noticing the quiet 'knower' behind today's sensations and moods—real knowledge begins in telling the two apart.", "insight": "Wisdom is discerning the conscious witness from the changing field of body, mind, and circumstance."},
  "तेषामेवानुकम्पार्थमहमज्ञानजं तमः । नाशयाम्यात्मभावस्थो ज्ञानदीपेन भास्वता ॥": {"reflection": "The light that dispels your confusion already dwells within you. Turn inward in sincere devotion, and trust that clarity comes as grace—not only as something you must force by sheer effort.", "insight": "The inner divine presence answers earnest seeking by itself dissolving the darkness of ignorance."},
  "मय्येव मन आधत्स्व मयि बुद्धिं निवेशय । निवसिष्यसि मय्येव अत ऊर्ध्वं न संशयः ॥": {"reflection": "Where your attention rests, you come to dwell. Give your mind and judgment to the highest you know, and slowly your whole life reorganizes around it rather than around scattered cravings.", "insight": "We become what we steadily attend to; sustained devotion of mind and intellect is itself the path to union."},
  "अमानित्वमदम्भित्वमहिंसा क्षान्तिरार्जवम् । आचार्योपासनं शौचं स्थैर्यमात्मविनिग्रहः ॥": {"reflection": "Real knowledge shows up as character, not opinions. Humility, honesty, patience, and self-restraint in ordinary dealings are the proof that you have understood anything at all.", "insight": "Wisdom is defined here as cultivated virtue and conduct, not mere intellectual information."},
  "तुम्हेहि किच्चं आतप्पं, अक्खातारो तथागता।": {"reflection": "No teacher, book, or app can walk the road for you. Guidance points the direction, but the daily effort of changing your own mind is work only you can do.", "insight": "Liberation requires personal exertion; teachers can show the way but cannot make the journey for us."},
  "衆生本来仏なり。": {"reflection": "You are not a broken thing trying to become worthy. Your awakened nature is already present beneath the noise; practice uncovers it rather than manufacturing it.", "insight": "Enlightenment is the recognition of an innate Buddha-nature, not the acquisition of something foreign."},
  "चातुर्वर्ण्यं मया सृष्टं गुणकर्मविभागशः। तस्य कर्तारमपि मां विद्ध्यकर्तारमव्ययम्॥": {"reflection": "Roles in society arise from differing temperaments and the work people are drawn to. Hold your own role lightly, knowing the unchanging Self within is never bound by the function it performs.", "insight": "Divisions of work flow from qualities and action, yet the changeless Self remains the non-doer behind them."},
  "अन्तकाले च मामेव स्मरन्मुक्त्वा कलेवरम्। यः प्रयाति स मद्भावं याति नास्त्यत्र संशयः॥": {"reflection": "What fills the final moment is shaped by a lifetime of habit. Remember the highest now, daily, so that remembrance is natural when you most need it.", "insight": "The state of consciousness at death reflects lifelong practice and determines what one attains."},
  "मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु। मामेवैष्यसि युक्त्वैवमात्मानं मत्परायणः॥": {"reflection": "Devotion is not one separate hour but a whole orientation: thought, worship, and bowing all turned the same way. Let the sacred become the axis your ordinary day quietly turns around.", "insight": "Complete absorption of mind, action, and reverence in the Divine is itself the means of reaching it."},
  "तुम्हरे भजन राम को पावै। जनम जनम के दुख बिसरावै॥": {"reflection": "Sincere remembrance and praise lift the weight of old griefs. When the heart turns toward the divine through song, accumulated sorrows lose their grip.", "insight": "Devotional praise becomes a doorway to the divine and a release from long-carried suffering."},
  "教外別傳 不立文字 直指人心 見性成佛": {"reflection": "Truth can be studied endlessly and still be missed. Set the explanations down at times and look directly at your own mind, where understanding actually lives.", "insight": "Awakening is a direct seeing into one's own nature, beyond what words and texts can transmit."},
  "廓然無聖。": {"reflection": "Drop the ranking of sacred over ordinary. When you stop straining to be holy, the open spaciousness of this very moment is enough.", "insight": "Ultimate reality is vast and empty of fixed categories, including the idea of the holy itself."},
  "ममैवांशो जीवलोके जीवभूतः सनातनः । मनःषष्ठानीन्द्रियाणि प्रकृतिस्थानि कर्षति ॥": {"reflection": "Your restlessness is the eternal in you straining against the pull of the senses and the mind. Remember your true source, and the struggle softens into homesickness for it.", "insight": "The living self is an eternal fragment of the Divine, presently laboring under the tug of the six senses."},
  "यथा मे सङ्कप्पो समिज्झि, एवं तुम्हाकम्पि समिज्झतू ति।": {"reflection": "Punishing the body did not bring Siddhartha clarity; nourishment and balance did. Tend your own strength honestly, for extremes of self-denial dull the very mind you hope to free.", "insight": "The Middle Way teaches that wisdom needs a cared-for body, not self-torture, to ripen."},
  "盗人に取り残されし窓の月": {"reflection": "What can be stolen was never your true wealth. Even after every loss, the quiet, freely given beauty of this moment remains at your window.", "insight": "The deepest riches lie in what cannot be taken, and loss can reveal that abundance."},
  "不生の仏心で居りなされ。": {"reflection": "Beneath every passing mood is a mind that was never born and cannot be disturbed. Rest there instead of chasing each thought, and you find a stillness already yours.", "insight": "Peace comes from abiding in the unborn, unconditioned awareness rather than in fleeting mental states."},
  "ॐ वज्रसत्त्व समयमनुपालय । वज्रसत्त्वत्वेनोपतिष्ठ । दृढो मे भव । सुतोष्यों मे भव । सुपोष्यों मे भव । अनुरक्तो मे भव । सर्वसिद्धिं मे प्रयच्छ । सर्वकर्मसु च मे चित्तं श्रियं कुरु हूँ । ह ह ह ह होः भगवन् सर्वतथागतवज्र मा मे मुञ्च । वज्री भव महासमयसत्त्व आः ॥": {"reflection": "This is a prayer to honor commitments and to be made steadfast and lucid. Renew your own broken vows honestly, asking for the steadiness to keep your word in all your actions.", "insight": "Purification begins with sincerely renewing one's commitments and seeking an unwavering, clear mind."},
  "नमोऽमिताभाय बुद्धाय": {"reflection": "Turning toward boundless light is itself a humbling and a hope. A simple act of homage reorients the day away from self-preoccupation toward something vast and merciful.", "insight": "Reverent invocation of infinite light expresses trust in a grace greater than one's own effort."},
  "यश्च वर्षशतं जीवेदपश्यन्नमृतं पदम् । एकाहं जीवितं श्रेयः पश्यतोऽमृतं पदम् ॥": {"reflection": "Length of life matters less than depth of seeing. A single day lived in clear awareness of the deathless outweighs decades spent asleep to it.", "insight": "The quality of awakened insight, not mere duration, gives a life its true worth."},
  "रूपं शून्यता शून्यतैव रूपम् । रूपान्न पृथक् शून्यता शून्यताया न पृथग् रूपम् ॥": {"reflection": "The things you cling to and the openness you fear are not two. Hold experiences as real yet fluid, and you can engage life fully without grasping it too tightly.", "insight": "Form and emptiness are inseparable; appearances are real yet empty of fixed, independent existence."},
  "ब्रह्मार्पणं ब्रह्म हविर्ब्रह्माग्नौ ब्रह्मणा हुतम् । ब्रह्मैव तेन गन्तव्यं ब्रह्मकर्मसमाधिना ॥": {"reflection": "When you cook, work, or serve seeing the act, the doer, and the gift as one sacred whole, ordinary tasks become offerings. Such absorbed attention turns daily labor into a path home.", "insight": "When the act, the means, and the doer are all seen as the divine, every action becomes worship and leads to the divine."},
  "सब्बे सङ्खारा दुक्खाति यदा पञ्ञाय पस्सति । अथ निब्बिन्दती दुक्खे एस मग्गो विसुद्धिया ॥": {"reflection": "Notice how even pleasant things carry an undertone of strain because they cannot last. Seeing this clearly loosens your grip on them, and that loosening, not more grasping, is what brings peace.", "insight": "Wisely recognizing that all conditioned things are unsatisfactory frees the heart from clinging and purifies it."},
  "सब्बे धम्मा अनत्ताति यदा पञ्ञाय पस्सति । अथ निब्बिन्दती दुक्खे एस मग्गो विसुद्धिया ॥": {"reflection": "Much suffering comes from defending a fixed idea of who 'I' am. Seeing that no experience contains a solid, owned self softens that defensiveness and brings a quieter, freer way of living.", "insight": "Discerning that all phenomena are without a fixed self releases clinging and opens the path to purity."},
  "應無所住而生其心": {"reflection": "Act and respond fully, but without your mind sticking to praise, outcome, or grievance. Let attention arise fresh for each moment rather than clinging to the last one.", "insight": "True clarity arises when the mind engages wholly yet rests on nothing."},
  "अत्थि भिक्खवे अजातं अभूतं अकतं असङ्खतं । नो चे तं भिक्खवे अभविस्स अजातं अभूतं अकतं असङ्खतं नयिध जातस्स भूतस्स कतस्स सङ्खतस्स निस्सरणं पञ्ञायेथ ॥": {"reflection": "Everything you build, achieve, and become is made and will pass. This verse points to something unmade and unconditioned, and it is the reality of that unmade that makes genuine release from the churn of conditions possible.", "insight": "Freedom from the conditioned is possible only because there exists an unconditioned reality."},
  "न परेसं विलोमानि न परेसं कताकतं । अत्तनो व अवेक्खेय्य कतानि अकतानि च ॥": {"reflection": "Tracking others' faults and failures drains energy and changes nothing. Turn that gaze inward instead: what have I done, and what have I left undone? That is the work actually within your reach.", "insight": "Inner growth comes from honestly examining one's own conduct rather than auditing others'."},
  "आरोग्यपरमा लाभा सन्तुट्ठिपरमं धनं । विस्सासपरमा ञाती निब्बानं परमं सुखं ॥": {"reflection": "Before chasing more, take stock of what you already hold: health, contentment, and people who trust you. This verse ranks these above ordinary gain, and naming them daily steadies the heart.", "insight": "The truest riches are health, contentment, and trust, with liberation as the highest happiness of all."},
  "अत्ता हि अत्तनो नाथो अत्ता हि अत्तनो गति । तस्मा सञ्ञमयत्तानं अस्सं भद्रं व वाणिजो ॥": {"reflection": "No one else can master your impulses for you. Tend yourself with the same firm, patient care a trader gives a fine horse, and you become your own reliable refuge.", "insight": "You are your own protector, so self-discipline is the foundation of a guided life."},
  "渠今正是我，我今不是渠。": {"reflection": "What you see and meet in the world reflects you, yet you are more than any single reflection. Hold this paradox lightly: recognize yourself everywhere without mistaking any one thing for the whole of you.", "insight": "The self is reflected in all it perceives, yet is never reducible to any of those reflections."},
  "सुसुखं वत जीवाम वेरिंसु अवेरिना । वेरिंसु मनुस्सेसु अवेरिना विहराम ॥": {"reflection": "When those around you carry hostility, you need not absorb it. Choosing not to return hatred is not weakness but freedom, and the lightness it brings is its own quiet reward.", "insight": "True happiness lies in living free of hatred even amid those who harbor it."},
  "ॐ मणिपद्मे हूँ": {"reflection": "Repeating this invocation gathers a scattered mind and turns it toward compassion and awakening. Even a few mindful recitations can re-center a restless day around what is sacred.", "insight": "The jewel within the lotus points to awakened compassion held at the heart of practice."},
  "गते गते पारगते पारसंगते बोधि स्वाहा": {"reflection": "Life moves through one crossing after another, each leaving something behind. This mantra celebrates that journey of letting go all the way to awakening, encouraging you to keep moving beyond what no longer serves.", "insight": "Liberation is a progressive going-beyond, culminating in complete awakening."},
  "नमो तस्स भगवतो अरहतो सम्मासम्बुद्धस्स": {"reflection": "Beginning practice with homage to one who awakened fully reminds you that the path has been walked before. A moment of reverence sets a humble, aspiring tone for whatever follows.", "insight": "Paying homage to the awakened one honors the realized ideal that practice aspires toward."},
  "狗子還有佛性也無？州云、無。": {"reflection": "When a real question grips you, no tidy yes-or-no answer satisfies it. Zhaozhou's 'Mu' invites you to sit with the question itself rather than rush to resolve it, letting inquiry deepen you.", "insight": "Some truths are met not by choosing an answer but by passing through the question itself."},
  "南無阿彌陀佛": {"reflection": "When your own strength feels insufficient, this invocation turns the heart toward boundless light and grace beyond the self. Saying it sincerely is an act of trust as much as devotion.", "insight": "Devotion entrusts the heart to a compassion and light greater than one's own effort."},
  "दृष्ट्वा तु पाण्डवानीकं व्यूढं दुर्योधनस्तदा। आचार्यमुपसङ्गम्य राजा वचनमब्रवीत्॥": {"reflection": "Seeing the opposing army drawn up, Duryodhana goes straight to his teacher to speak. Even an uneasy heart instinctively reaches for counsel when facing something larger than expected.", "insight": "When confronted by a formidable challenge, the instinct to turn toward guidance reveals our need for counsel."},
  "सेनयोरुभयोर्मध्ये रथं स्थापय मेऽच्युत।": {"reflection": "Before acting, Arjuna asks to be placed where he can see clearly between both sides. Pause to take in the whole situation before deciding, addressing the steady presence you trust to help you see.", "insight": "Clear seeing of the full situation must precede right action."},
  "न जायते म्रियते वा कदाचिन्नायं भूत्वा भविता वा न भूयः। अजो नित्यः शाश्वतोऽयं पुराणो न हन्यते हन्यमाने शरीरे॥": {"reflection": "When fear of loss or death presses in, this verse points to what in you was never born and cannot die. Resting attention there brings a steadiness that bodily change cannot disturb.", "insight": "The true self is unborn and deathless, untouched by the body's birth and decay."},
  "यज्ञार्थात्कर्मणोऽन्यत्र लोकोऽयं कर्मबन्धनः। तदर्थं कर्म कौन्तेय मुक्तसङ्गः समाचर॥": {"reflection": "Do your daily work as an offering rather than for what you can grab from it, and the same tasks that once chained you with anxiety become free, unburdened action.", "insight": "Work performed as sacrifice liberates, while work done for selfish attachment binds."},
  "कर्मण्यकर्म यः पश्येदकर्मणि च कर्म यः। स बुद्धिमान्मनुष्येषु स युक्तः कृत्स्नकर्मकृत्॥": {"reflection": "Stay inwardly still and unattached even while busy, and notice that idleness can still be entangled striving; true wisdom is freedom of mind, not absence of activity.", "insight": "Liberation lies in one's inner relationship to action, not in doing or not doing."},
  "योगयुक्तो विशुद्धात्मा विजितात्मा जितेन्द्रियः। सर्वभूतात्मभूतात्मा कुर्वन्नपि न लिप्यते॥": {"reflection": "When you master your own mind and senses and recognize the same self in everyone, you can act fully in the world without being stained or trapped by what you do.", "insight": "Self-mastery and seeing oneself in all beings let one act without being entangled."},
  "न हि रुण्णेन सोकेन, सन्तिं पप्प‍ोति चेतसो।": {"reflection": "When grief overwhelms you, remember Kisa Gotami: every household carries its own losses. Recognizing that suffering is shared, not yours alone, is where the heart begins to find peace.", "insight": "Peace of mind comes not through weeping and sorrow but through accepting the universality of loss."},
  "योगिनामपि सर्वेषां मद्गतेनान्तरात्मना। श्रद्धावान्भजते यो मां स मे युक्ततमो मतः॥": {"reflection": "Among all spiritual paths, the one who holds the Divine in the heart with steady faith and love is closest of all; sincere devotion matters more than technique.", "insight": "Faithful, loving remembrance of the Divine is the most intimate form of union."},
  "येषां त्वन्तगतं पापं जनानां पुण्यकर्मणाम्। ते द्वन्द्वमोहनिर्मुक्ता भजन्ते मां दृढव्रताः॥": {"reflection": "As a life of good actions clears away inner corruption, you stop being tossed between pleasure and pain, like and dislike, and can serve the Divine with steady resolve.", "insight": "Purity of conduct frees one from the delusion of opposites and enables firm devotion."},
  "ओमित्येकाक्षरं ब्रह्म व्याहरन्मामनुस्मरन्। यः प्रयाति त्यजन्देहं स याति परमां गतिम्॥": {"reflection": "What fills the mind at the end is what one has practiced all along; cultivate remembrance of the Divine now, so that even your final breath rests in that highest refuge.", "insight": "A life of steady remembrance shapes the state in which one departs and the destination one reaches."},
  "त्वमादिदेवः पुरुषः पुराणस्त्वमस्य विश्वस्य परं निधानम् । वेत्तासि वेद्यं च परं च धाम त्वया ततं विश्वमनन्तरूप ॥": {"reflection": "Stand in awe: the same reality you seek to know is the knower within you and the ground beneath all things. The whole universe rests in and is pervaded by the Divine.", "insight": "The Divine is at once the knower, the known, and the ultimate refuge pervading all existence."},
  "समं सर्वेषु भूतेषु तिष्ठन्तं परमेश्वरम् । विनश्यत्स्वविनश्यन्तं यः पश्यति स पश्यति ॥": {"reflection": "Bodies age and pass, but the same imperishable Self dwells equally in everyone. Seeing this steadies you through change and dissolves the urge to rank one being above another.", "insight": "True vision perceives the one undying Self present equally within all perishable bodies."},
  "मां च योऽव्यभिचारेण भक्तियोगेन सेवते । स गुणान्समतीत्यैतान्ब्रह्मभूयाय कल्पते ॥": {"reflection": "Devotion that holds firm through every circumstance, good or bad, lifts you beyond the pull of moods and tendencies into a steady, boundless inner freedom.", "insight": "Unwavering devotion carries one beyond the modes of nature to the level of Brahman."},
  "त्रिविधं नरकस्येदं द्वारं नाशनमात्मनः । कामः क्रोधस्तथा लोभस्तस्मादेतत्त्रयं त्यजेत् ॥": {"reflection": "Craving, anger, and greed quietly wreck a life from within. Watch for these three at their first stirring and let them go, for guarding against them protects your own well-being.", "insight": "Lust, anger, and greed are the three gateways to self-destruction and must be relinquished."},
  "सत्त्वानुरूपा सर्वस्य श्रद्धा भवति भारत । श्रद्धामयोऽयं पुरुषो यो यच्छ्रद्धः स एव सः ॥": {"reflection": "What you place your faith in quietly shapes who you become. Examine where your deepest trust rests, for a person is, in the end, made of their faith.", "insight": "A person's character is formed by the quality of faith they hold."},
  "ईश्वरः सर्वभूतानां हृद्देशेऽर्जुन तिष्ठति । भ्रामयन्सर्वभूतानि यन्त्रारूढानि मायया ॥": {"reflection": "Recognize how much of life moves you like a machine through habit and circumstance, and turn toward the Divine seated in your own heart, the still center beneath all that motion.", "insight": "The Lord dwells in every heart, guiding beings who are carried along by material nature."},
  "सर्वस्य चाहं हृदि सन्निविष्टो मत्तः स्मृतिर्ज्ञानमपोहनं च । वेदैश्च सर्वैरहमेव वेद्यो वेदान्तकृद्वेदविदेव चाहम् ॥": {"reflection": "Memory, understanding, and even forgetting arise from the Divine within your heart. When recall fails or clarity comes, turn there in trust rather than only to your own effort.", "insight": "The same Divine seated in the heart is the source of memory, knowledge, and forgetfulness, and the goal of all sacred learning."},
  "ॐ तारे तुत्तारे तुरे स्वाहा": {"reflection": "When fear or obstacles close in, call on Tara the swift liberator; this mantra turns the heart toward the compassionate power that carries beings across difficulty.", "insight": "Devotion to Tara invokes liberating compassion that delivers beings from fear and bondage."},
  "ཨོཾ་ཨཱཿཧཱུྃ་བཛྲ་གུ་རུ་པདྨ་སིདྡྷི་ཧཱུྃ": {"reflection": "This mantra calls on Padmasambhava, the diamond teacher, asking for both everyday and supreme attainments; reciting it is an act of trust in the guru's guiding power.", "insight": "Invoking the Vajra Guru seeks both ordinary and supreme spiritual accomplishment."},
  "ॐ मुने मुने महामुनये स्वाहा": {"reflection": "Honoring Shakyamuni, the great sage, this mantra orients the heart toward awakened wisdom; chanting it is a bow to the one who showed the path out of suffering.", "insight": "The mantra pays homage to the Buddha as the supreme embodiment of sage-like wisdom."},
  "ॐ अरपचन धीः": {"reflection": "This mantra salutes Manjushri, who embodies wisdom itself; reciting it, especially the seed syllable Dhih, is a call to sharpen clear, discerning understanding.", "insight": "Homage to Manjushri invokes the awakening of pure, penetrating wisdom."},
  "राजाहं तेसं पवरो, तेसं अत्थाय मे वधो।": {"reflection": "When you hold any kind of authority—over a team, a family, a child—the Monkey King teaches that real leadership means your body and comfort serve those in your care, not the other way around. Put their safety before your own ease.", "insight": "True authority is measured by the willingness to bear cost so that those who depend on you may be spared it."},
  "तद्यथा ॐ भैषज्ये भैषज्ये महाभैषज्ये राजसमुद्गते स्वाहा": {"reflection": "When illness strikes you or someone you love, this invocation lets you turn helplessness into a steady act of goodwill—wishing swiftly for healing while you also do the practical, caring work that healing requires.", "insight": "Compassion for the sick can take the form of focused, reverent intention as much as of medicine."},
  "प्रजहाति यदा कामान्सर्वान्पार्थ मनोगतान्। आत्मन्येवात्मना तुष्टः स्थितप्रज्ञस्तदोच्यते॥": {"reflection": "Lasting steadiness comes not from acquiring the next thing the mind craves, but from finding sufficiency within yourself. When your peace no longer depends on cravings being met, no day can fully shake you.", "insight": "Wisdom becomes unshakable when contentment is sourced from the self rather than from satisfying desire."},
  "मनःप्रसादः सौम्यत्वं मौनमात्मविनिग्रहः । भावसंशुद्धिरित्येतत्तपो मानसमुच्यते ॥": {"reflection": "Discipline is not only what you do with your body; cultivating a calm, gentle, quiet mind and honest intentions is its own demanding practice. Guarding your inner tone is a real austerity, worth daily effort.", "insight": "The hardest discipline is inward: serenity, gentleness, restraint, and purity of intention."},
  "अत्तदण्डा भयं जातं जनं पस्सथ मेधकं । संवेगं कित्तयिस्सामि यथा संविजितं मया ॥": {"reflection": "Notice how fear and conflict spread wherever people reach for weapons and quarreling. Letting that recognition genuinely shake you can become the spur that turns you away from violence and toward peace.", "insight": "Seeing clearly how conflict breeds fear can awaken the urgency that moves us toward a peaceful path."},
  "सेलो यथा एकघनो वातेन न समीरति । एवं निन्दापसंसासु न समिञ्जन्ति पण्डिता ॥": {"reflection": "Praise lifts us and criticism stings, but both are passing winds. Like solid rock, let your sense of worth rest on what you know to be right, so neither flattery nor blame blows you off course.", "insight": "Inner steadiness means neither inflating at praise nor collapsing at blame."},
  "नहेव कुञ्जरमासादो, दुक्खं हि कुञ्जरमासादो।": {"reflection": "When someone charges at you in rage, the Buddha's calm before Nalagiri shows another way: meeting hostility with steady loving-kindness rather than fear or counter-force can disarm what no resistance could.", "insight": "Genuine, fearless compassion can quiet aggression that force would only inflame."},
  "इदं वयो रूपमदं हरति, स्मृतिं मुष्णाति, बलं लुनाति।": {"reflection": "Age, sickness, and death come to everyone, however sheltered. Rather than denying this, let it sharpen your purpose—Siddhartha's honest look at impermanence is what set him searching for what truly lasts.", "insight": "Facing the fragility of youth and life honestly is the beginning of the search for truth."},
  "छिन्दामि तं मयि बन्धनं।": {"reflection": "Sometimes growth asks us to cut a tie to something we are proud of—a status, an image, a comfort. Siddhartha's severing of his royal hair shows that real commitment often begins with a clean, decisive renunciation.", "insight": "Pursuing truth can demand cutting away even the things that most flatter our sense of self."},
  "अहो बत मे अद्य सफलोऽयं देहोत्सर्गः।": {"reflection": "Mahasattva's gift is extreme, but its spirit is daily: when another being is truly desperate, compassion sometimes calls us to give beyond what is comfortable. Let mercy, not self-protection, have the final word.", "insight": "Boundless compassion treats the body and its comforts as instruments for relieving another's suffering."},
  "तारका तिमिरं दीपो मायावश्यायबुद्बुदम् । सुपिनं विद्युदभ्रं च एवं द्रष्टव्यसंस्कृतम् ॥": {"reflection": "The things we grip most tightly—achievements, worries, even our moods—are as fleeting as dew or a lightning flash. Holding them lightly frees you to act without being crushed when they pass.", "insight": "All constructed things are fleeting; seeing their impermanence loosens our grip on them."},
  "सत्था देवलोका ओतरन्तो... तिदसापुरतो ओतरि।": {"reflection": "The Buddha climbed to heaven to repay his mother by teaching her. Whatever we have received from our parents, the deepest gratitude takes the form of giving back something of lasting worth, not just words.", "insight": "The truest repayment of a parent's gift of life is to offer them something of enduring value."},
  "तस्मातिह ते बाहिय एवं सिक्खितब्बं: दिट्ठे दिट्ठमत्तं भविस्सति, सुते सुतमत्तं भविस्सति, मुते मुतमत्तं भविस्सति, विञ्ञाते विञ्ञातमत्तं भविस्सतीति ॥": {"reflection": "Much of our suffering comes from the stories we pile onto what we see and hear. Try letting the seen be just seen and the heard just heard—meeting each moment plainly, before judgment rushes in.", "insight": "Freedom grows when we meet experience as it is, without the added overlay of reactive interpretation."},
  "यमकपाटिहारियं कत्वा... (Yamaka-pāṭihāriyaṃ katvā...)": {"reflection": "The Twin Miracle united opposites—fire and water—in a single being. It is a reminder that integration, not the elimination of one side of life, is the mark of a fully realized mind.", "insight": "Awakening reconciles opposites that ordinarily seem to cancel each other out."},
  "यतो यतो याचनका आगच्छन्ति... ततो ततो ददामि।": {"reflection": "Vessantara's vow to never refuse a request is extreme, yet it points to a livable virtue: practicing open-handed generosity, giving freely where you can rather than clutching what you have.", "insight": "Perfecting generosity means loosening attachment to what we hold, giving wherever there is genuine need."},
  "鉢の子に明日の米あり夕涼み": {"reflection": "Enough for tomorrow, and a cool evening to enjoy—this is contentment in its simplest form. Notice how little you actually need to feel at ease, and let that quiet sufficiency be enough today.", "insight": "Contentment asks not for abundance but for enough, met with a peaceful heart."},
  "露の世は露の世ながらさりながら": {"reflection": "Issa wrote this in grief, knowing life is fleeting as dew—and still he ached. It gives permission to hold both truths: accepting impermanence does not require pretending the heart does not break.", "insight": "Wisdom about impermanence and the honest pain of loss can, and do, live together."},
  "吾有正法眼藏，涅槃妙心，實相無相，微妙法門...": {"reflection": "Mahakasyapa understood the flower without a word spoken. Some of the deepest things we learn—and teach—pass through presence, attention, and shared silence rather than explanation.", "insight": "The most essential understanding is transmitted directly, beyond the reach of words."},
  "सुखो विवेको तुट्ठस्स, सुतधम्मस्स पस्सतो।": {"reflection": "The Buddha named solitude, contentment, and harmlessness as true happiness. Today, choose the quiet hour over the crowded feed, and meet others without wishing them harm—that is where ease actually lives.", "insight": "Lasting happiness comes from inner contentment and goodwill, not from circumstances that must always be controlled."},
  "परित्राणाय साधूनां विनाशाय च दुष्कृताम्। धर्मसंस्थापनार्थाय सम्भवामि युगे युगे॥": {"reflection": "When wrong seems to be winning, this verse promises that the order behind life renews itself in every age. Keep doing right and protecting the good; you are aligned with that recurring restoration.", "insight": "The moral order of the universe is not static but self-renewing, reasserting righteousness whenever it declines."},
  "श्रीगुरु चरन सरोज रज, निज मनु मुकुरु सुधारि। बरनउँ रघुबर बिमल जसु, जो दायकु फल चारि॥ बुद्धिहीन तनु जानिके, सुमिरौं पवन-कुमार। बल बुधि बिद्या देहु मोहिं, हरहु कलेस बिकार॥": {"reflection": "Begin any real work by first cleaning the mirror of your mind and honestly admitting what you lack. Asking for strength, clarity, and knowledge with humility prepares you far better than pretending you already have them.", "insight": "Genuine effort starts with a purified, humble mind that openly acknowledges its own limitations."},
  "देहिनोऽस्मिन्यथा देहे कौमारं यौवनं जरा । तथा देहान्तरप्राप्तिर्धीरस्तत्र न मुह्यति ॥": {"reflection": "You did not panic when childhood gave way to youth, or youth to age. Hold change—even the body's final change—with that same steadiness; the witnessing self continues through every passage.", "insight": "The conscious self that persists through life's stages is untouched by the bodily transitions it observes."},
  "विद्याविनयसम्पन्ने ब्राह्मणे गवि हस्तिनि। शुनि चैव श्वपाके च पण्डिताः समदर्शिनः॥": {"reflection": "True wisdom shows itself as equal regard for the learned and the outcast, the powerful and the lowly. Practice it by treating the person who can do nothing for you exactly as you treat the one who can.", "insight": "Real knowledge perceives the same essence within all beings, dissolving the rankings imposed by status."},
  "नैनं छिन्दन्ति शस्त्राणि नैनं दहति पावकः । न चैनं क्लेदयन्त्यापो न शोषयति मारुतः ॥": {"reflection": "Loss, illness, and insult can wound the body and circumstances, but not the essential self at your core. In hard moments, remember there is something in you that no harm can actually reach.", "insight": "The true Self is indestructible, untouched by any force that can damage the physical and material."},
  "योगस्थः कुरु कर्माणि सङ्गं त्यक्त्वा धनञ्जय । सिद्ध्यसिद्ध्योः समो भूत्वा समत्वं योग उच्यते ॥": {"reflection": "Do your work fully, then release your grip on how it turns out. Meeting both success and failure with the same steady mind keeps you free while still giving your best.", "insight": "Yoga is the inner evenness that lets you act wholeheartedly while remaining unattached to results."},
  "वासांसि जीर्णानि यथा विहाय नवानि गृह्णाति नरोऽपराणि । तथा शरीराणि विहाय जीर्णान्यन्यानि संयाति नवानि देही ॥": {"reflection": "We change worn-out clothes without grief. This verse asks us to see the body the same way—an outer garment of the deathless self—so that mortality loosens its grip of fear.", "insight": "The body is a temporary garment of the enduring soul, making death a transition rather than an end."},
  "悟りの前、薪を割り、水を運ぶ。悟りの後、薪を割り、水を運ぶ。": {"reflection": "Awakening does not hand you a different life; it transforms how you meet the same chores. The dishes and the commute remain—but done with presence, the ordinary becomes the practice itself.", "insight": "Enlightenment changes the quality of attention we bring to ordinary tasks, not the tasks themselves."},
  "燭の火を燭にうつすや春の夕": {"reflection": "One flame lights another and loses nothing. When you pass on what you know or share warmth with someone, your own light is not diminished but quietly multiplied.", "insight": "Wisdom and kindness, like flame, are given without loss to the giver."},
  "仏に逢えば仏を殺せ": {"reflection": "If you have turned awakening into an image to chase or an authority to worship, let that image go. The teaching warns against clinging even to your loftiest spiritual concepts.", "insight": "Attachment to any fixed idea of truth—even the holiest—becomes an obstacle to realizing it directly."},
  "夏草や兵どもが夢の跡": {"reflection": "Where armies once fought for glory, only summer grass now grows. Let this temper your striving for status and conquest; hold your ambitions lightly, for time levels them all.", "insight": "The grand pursuits of power and fame are impermanent, soon reclaimed by quiet nature."},
  "बुद्धियुक्तो जहातीह उभे सुकृतदुष्कृते । तस्माद्योगाय युज्यस्व योगः कर्मसु कौशलम् ॥": {"reflection": "Acting from a balanced mind, without grasping at reward, frees you from the anxious ledger of merit and blame. Bring that skill—full effort, no clinging—to whatever you do today.", "insight": "Skillful action performed in equanimity releases one from the binding weight of both good and bad deeds."},
  "朝顔に釣瓶とられてもらい水": {"reflection": "Rather than tear away a flower that had wrapped the well bucket overnight, the poet went elsewhere for water. Small courtesies toward life—a willingness to be inconvenienced for beauty—reveal a gentle heart.", "insight": "Reverence for life is shown in the readiness to yield our convenience rather than harm what is fragile."},
  "花は愛惜に散り、草は棄嫌に生ずるのみなり。": {"reflection": "What we love still fades, and what we resist still arrives. Accepting this without quarrel lets you love fully and meet the unwanted with less bitterness.", "insight": "Reality unfolds independent of our preferences, and peace begins where resistance to that truth ends."},
  "蝸牛そろそろ登れ富士の山": {"reflection": "The mountain is vast and the snail is slow, yet the verse says climb anyway—slowly. Honor your own steady pace toward a great goal; small, patient steps are still the way up.", "insight": "Worthy ends are reached not by speed but by patient, unhurried persistence."},
  "茶の湯とはただ湯をわかし茶をたてて飲むばかりなる本を知るべし": {"reflection": "The whole art of tea is just boiling water, making it, and drinking it. Likewise, much of life's depth is found by doing simple things completely and attentively, without inflating them.", "insight": "Mastery and meaning lie in giving full, simple attention to the plain act before you."},
  "初心者の心には多くの可能性がありますが、専門家の心にはほとんどありません。": {"reflection": "Expertise can quietly close doors, making us assume we already know. Approach familiar work as if for the first time, and you reopen possibilities the practiced mind had stopped seeing.", "insight": "An open, unassuming mind perceives more possibilities than one hardened by accumulated expertise."},
};
